/* ================= FISIKA ================= */
/* Gambar tangga satuan. hi = [indeks asal, indeks tujuan] untuk disorot (dipakai juga oleh lab). */
function tanggaSVG(u, k, c, judul, hi, cls = 'tangga') {
  const n = u.length, w = 288 / n, h = 17, x0 = 16, y0 = 50, base = y0 + (n - 1) * h + 30;
  const X = i => x0 + i * w, Y = i => y0 + i * h, CX = i => X(i) + w / 2;
  let d = `M${x0} ${base} L${x0} ${y0}`;
  for (let i = 0; i < n; i++) { d += ` L${X(i + 1)} ${Y(i)}`; if (i < n - 1) d += ` L${X(i + 1)} ${Y(i + 1)}`; }
  d += ` L${X(n)} ${base} Z`;
  const kk = k.toLocaleString('id-ID');
  const who = hi ? hi[0] : 0, to = hi ? hi[1] : n - 1, down = to >= who;
  const ya = i => Y(i) - 26, mid = (CX(who) + CX(to)) / 2;
  const arc = who === to ? '' : `<path d="M${CX(who)} ${ya(who) + 4} Q${mid} ${Math.min(ya(who), ya(to)) - 18} ${CX(to)} ${ya(to) + 8}" fill="none" stroke="${down ? '#16a34a' : '#e11d48'}" stroke-width="2.5" stroke-dasharray="${hi ? '0' : '6 4'}" marker-end="url(#tgA${down ? 'g' : 'r'})"/>`;
  return `<svg class="${cls}" viewBox="0 0 320 ${base + 34}" width="320" style="max-width:100%;display:block;margin:10px auto">
  <defs><marker id="tgAg" markerWidth="8" markerHeight="8" refX="4" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="#16a34a"/></marker><marker id="tgAr" markerWidth="8" markerHeight="8" refX="4" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="#e11d48"/></marker>
  <linearGradient id="tgG${c.slice(1)}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${c}"/><stop offset="1" stop-color="${c}" stop-opacity=".55"/></linearGradient></defs>
  <text x="160" y="14" text-anchor="middle" font-size="12.5" font-weight="700" fill="#16323f">${judul}</text>
  <path d="${d}" fill="url(#tgG${c.slice(1)})"/>` +
  u.map((t, i) => { const on = hi && (i === hi[0] || i === hi[1]);
    return `<line x1="${X(i)}" y1="${Y(i)}" x2="${X(i + 1)}" y2="${Y(i)}" stroke="${on ? (i === hi[0] ? '#1d4ed8' : '#f59e0b') : '#ffffff'}" stroke-width="${on ? 5 : 2.5}" stroke-linecap="round"/>
    <text x="${CX(i)}" y="${Y(i) + 14}" text-anchor="middle" font-size="${t.length > 3 ? 10.5 : 12}" font-weight="700" fill="#fff">${t}</text>`; }).join('') +
  arc + `<text x="${CX(who)}" y="${Y(who) - 3}" text-anchor="middle" font-size="20">🧒</text>${who !== to ? `<text x="${CX(to)}" y="${Y(to) - 3}" text-anchor="middle" font-size="16">🚩</text>` : ''}
  <text x="16" y="${base + 14}" font-size="11.5" font-weight="700" fill="#16a34a">⬇ turun 1 anak tangga = × ${kk}</text>
  <text x="304" y="${base + 30}" text-anchor="end" font-size="11.5" font-weight="700" fill="#e11d48">⬆ naik 1 anak tangga = : ${kk}</text></svg>`;
}
const TG = {
  p: ['Panjang', ['km', 'hm', 'dam', 'm', 'dm', 'cm', 'mm'], 10, '#2f7de1'],
  m: ['Massa', ['kg', 'hg', 'dag', 'g', 'dg', 'cg', 'mg'], 10, '#8b5cf6'],
  l: ['Volume (liter)', ['kL', 'hL', 'daL', 'L', 'dL', 'cL', 'mL'], 10, '#0ea5e9'],
  a: ['Luas', ['km²', 'hm²', 'dam²', 'm²', 'dm²', 'cm²', 'mm²'], 100, '#16a34a'],
  v: ['Volume (kubik)', ['km³', 'hm³', 'dam³', 'm³', 'dm³', 'cm³', 'mm³'], 1000, '#e58a00'],
};
const tg = key => tanggaSVG(TG[key][1], TG[key][2], TG[key][3], 'Tangga satuan ' + TG[key][0].toLowerCase());
C({id:'f1', mapel:'fisika', no:1, ikon:'📏', judul:'Besaran & Satuan', lab:'satuan',
ringkas:'Besaran adalah segala sesuatu yang dapat diukur dan dinyatakan dengan angka serta satuan. Pelajari 7 besaran pokok, besaran turunan, dan tangga satuan untuk panjang, massa, liter, luas, serta volume.',
svg:tanggaSVG(['km','hm','dam','m','dm','cm','mm'],10,'#2f7de1','Tangga satuan panjang',null,'ill'),

sesi:[
{j:'Apa itu besaran dan satuan?', h:`<p>Perhatikan kalimat <b>“panjang meja 120 cm”</b>. Di dalamnya ada tiga hal:</p><ul><li><b>Besaran</b>: panjang (apa yang diukur)</li><li><b>Nilai</b>: 120 (berapa banyak)</li><li><b>Satuan</b>: cm (pembandingnya)</li></ul><p>Mengukur berarti <b>membandingkan</b> sesuatu dengan satuan. Hal yang tidak bisa dinyatakan dengan angka, misalnya “cantik” atau “rajin”, <b>bukan</b> besaran.</p><div class="note">💡 Satuan harus <b>baku</b> (sama di mana pun), contohnya meter. Jengkal dan depa tidak baku karena panjangnya berbeda tiap orang.</div>`},
{j:'Tujuh besaran pokok (SI)', h:`<p>Besaran pokok adalah besaran yang satuannya ditetapkan lebih dulu dan tidak diturunkan dari besaran lain.</p><div class="tbl"><table><tr><th>Besaran</th><th>Satuan SI</th><th>Simbol</th><th>Alat ukur</th></tr><tr><td>Panjang</td><td>meter</td><td>m</td><td>mistar, jangka sorong, mikrometer</td></tr><tr><td>Massa</td><td>kilogram</td><td>kg</td><td>neraca</td></tr><tr><td>Waktu</td><td>sekon</td><td>s</td><td>stopwatch</td></tr><tr><td>Suhu</td><td>kelvin</td><td>K</td><td>termometer</td></tr><tr><td>Kuat arus</td><td>ampere</td><td>A</td><td>amperemeter</td></tr><tr><td>Intensitas cahaya</td><td>kandela</td><td>cd</td><td>lux meter</td></tr><tr><td>Jumlah zat</td><td>mol</td><td>mol</td><td>—</td></tr></table></div><div class="note">🧠 Jembatan keledai: <b>“Pak Mas Waktu Suka Kuat Intan Jumlah”</b>.</div>`},
{j:'Besaran turunan', h:`<p>Besaran turunan disusun dari besaran pokok. Satuannya ikut turun dari rumusnya.</p><div class="tbl"><table><tr><th>Besaran</th><th>Rumus</th><th>Satuan</th></tr><tr><td>Luas</td><td>panjang × lebar</td><td>m²</td></tr><tr><td>Volume</td><td>p × l × t</td><td>m³</td></tr><tr><td>Kecepatan</td><td>jarak : waktu</td><td>m/s</td></tr><tr><td>Massa jenis</td><td>massa : volume</td><td>kg/m³</td></tr><tr><td>Percepatan</td><td>kecepatan : waktu</td><td>m/s²</td></tr><tr><td>Gaya</td><td>massa × percepatan</td><td>kg·m/s² = newton (N)</td></tr></table></div>`},
{j:'Tangga satuan panjang & massa', h:`<p>Satuan panjang dan massa disusun seperti <b>anak tangga</b>. Setiap <b>turun</b> satu anak tangga nilainya <b>dikali 10</b>; setiap <b>naik</b> satu anak tangga <b>dibagi 10</b>.</p>${tg('p')}<div class="f">2,5 km → m: turun 3 anak tangga → × 10 × 10 × 10 = × 1.000 → 2.500 m</div><div class="f">350 cm → m: naik 2 anak tangga → : 100 → 3,5 m</div>${tg('m')}<div class="f">450 g → kg: naik 3 anak tangga → : 1.000 → 0,45 kg</div><p>Satuan massa lain yang sering dipakai sehari-hari:</p><ul><li>1 <b>ton</b> = 10 kuintal = 1.000 kg</li><li>1 <b>kuintal</b> = 100 kg</li><li>1 <b>ons</b> = 1 hg = 100 g; 1 pon = 5 ons = 500 g</li></ul><div class="note">🧠 Urutan dari atas: <b>k</b>ilo – <b>h</b>ekto – <b>d</b>e<b>k</b>a – (satuan pokok) – <b>d</b>esi – <b>c</b>enti/senti – <b>m</b>ili. Hafalan: “<b>K</b>ita <b>H</b>arus <b>D</b>atang <b>M</b>alam <b>D</b>an <b>C</b>epat <b>M</b>akan”.</div>`},
{j:'Tangga satuan volume: liter', h:`<p>Volume zat cair biasanya memakai <b>liter (L)</b>. Tangga liter juga berkelipatan 10, sama seperti tangga panjang.</p>${tg('l')}<div class="f">2,5 L → mL: turun 3 anak tangga → × 1.000 → 2.500 mL</div><div class="f">600 mL → L: naik 3 anak tangga → : 1.000 → 0,6 L</div><p><b>Hubungan liter dengan satuan kubik</b> (penting untuk soal bak, akuarium, dan tangki):</p><div class="tbl"><table><tr><th>Satuan liter</th><th></th><th>Satuan kubik</th></tr><tr><td><b>1 kL</b></td><td>=</td><td><b>1 m³</b> = 1.000 L</td></tr><tr><td><b>1 L</b></td><td>=</td><td><b>1 dm³</b> = 1.000 cm³</td></tr><tr><td><b>1 mL</b></td><td>=</td><td><b>1 cm³</b> = 1 cc</td></tr></table></div>${tg('v')}<p>Pada tangga kubik setiap anak tangga bernilai <b>× 1.000</b>. Perhatikan posisinya: <b>m³ sejajar kL</b>, <b>dm³ sejajar L</b>, dan <b>cm³ sejajar mL</b>.</p><div class="f">1,5 m³ = 1.500 dm³ = 1.500 L &nbsp;|&nbsp; 250 cm³ = 250 mL = 0,25 L</div><div class="note">🥤 Contoh di label: botol air 600 mL = 0,6 L; obat sirup 5 mL = 5 cc = 1 sendok takar; galon 19 L = 19 dm³.</div>`},
{j:'Tangga satuan luas', h:`<p>Satuan luas adalah satuan panjang yang dikuadratkan, sehingga setiap anak tangga bernilai <b>× 100</b> (bukan × 10).</p>${tg('a')}<div class="f">4 m² → cm²: turun 2 anak tangga → × 100 × 100 = × 10.000 → 40.000 cm²</div><p><b>Satuan luas tanah</b>: <b>are</b> dan <b>hektare</b> berada di tangga yang sama:</p><ul><li>1 <b>are (a)</b> = 1 dam² = 100 m²</li><li>1 <b>hektare (ha)</b> = 1 hm² = 100 are = 10.000 m²</li><li>1 km² = 100 ha</li></ul><div class="f">3 ha = 3 × 10.000 m² = 30.000 m²</div>`},
{j:'Satuan waktu & kecepatan', h:`<div class="tbl"><table><tr><th>Satuan waktu</th><th>Kesetaraan</th></tr><tr><td>1 menit</td><td>60 detik (sekon)</td></tr><tr><td>1 jam</td><td>60 menit = 3.600 detik</td></tr><tr><td>1 hari</td><td>24 jam</td></tr><tr><td>1 minggu</td><td>7 hari</td></tr><tr><td>1 tahun</td><td>365 hari (366 tahun kabisat) = 12 bulan</td></tr><tr><td>1 windu · 1 dasawarsa · 1 abad</td><td>8 tahun · 10 tahun · 100 tahun</td></tr></table></div><p>Satuan waktu <b>tidak</b> berkelipatan 10, jadi tidak memakai tangga. Satuan gabungan diubah satu per satu:</p><div class="f">72 km/jam = 72.000 m / 3.600 s = 20 m/s &nbsp;|&nbsp; jalan pintas: km/jam : 3,6 = m/s, m/s × 3,6 = km/jam</div><p>Awalan SI yang penting: mega (M) = 10⁶, kilo (k) = 10³, hekto = 10², deka = 10¹, desi = 10⁻¹, senti (c) = 10⁻², mili (m) = 10⁻³, mikro (µ) = 10⁻⁶.</p>`},
{j:'Alat ukur dan ketelitiannya', h:`<ul><li><b>Mistar</b>: ketelitian 1 mm (0,1 cm). Baca dengan mata tegak lurus skala agar tidak terjadi kesalahan paralaks.</li><li><b>Jangka sorong</b>: ketelitian 0,1 mm (0,01 cm). Hasil = skala utama + (garis nonius yang berimpit × 0,01 cm). Bisa mengukur diameter dalam, luar, dan kedalaman.</li><li><b>Mikrometer sekrup</b>: ketelitian 0,01 mm. Hasil = skala utama + skala putar × 0,01 mm. Cocok untuk tebal kertas atau diameter kawat.</li></ul><div class="note">💡 Makin kecil nilai ketelitian, makin teliti alatnya.</div>`},
],
penemuan:`<h4>📜 Dari jengkal ke meter</h4><p>Dulu orang mengukur dengan bagian tubuh — jengkal, hasta, kaki — sehingga hasilnya berbeda-beda dan sering memicu sengketa dagang. Saat Revolusi Prancis (1790-an), para ilmuwan Prancis merancang <b>sistem metrik</b> yang berbasis 10.</p>
<div class="tl"><div><b>1791–1799</b> — 1 meter ditetapkan sebagai sepersepuluh juta jarak kutub utara ke khatulistiwa (diukur lewat Paris). 1 kilogram = massa 1 liter air.</div><div><b>1875</b> — 17 negara menandatangani Konvensi Meter; dibuat batang meter dan silinder kilogram standar dari platina-iridium.</div><div><b>1960</b> — disepakati <b>Sistem Internasional (SI)</b> dengan 7 satuan pokok.</div><div><b>2019</b> — semua satuan SI kini didefinisikan dari konstanta alam. Misalnya 1 meter = jarak tempuh cahaya di ruang hampa selama 1/299.792.458 sekon, sehingga bisa dibuat ulang di laboratorium mana pun.</div></div>
<h4>🪜 Mengapa tangga luas × 100 dan tangga kubik × 1.000?</h4><p>Karena 1 m = 10 dm, maka persegi bersisi 1 m berisi 10 × 10 = <b>100</b> persegi bersisi 1 dm → 1 m² = 100 dm². Sebuah kubus bersisi 1 m berisi 10 × 10 × 10 = <b>1.000</b> kubus kecil bersisi 1 dm → 1 m³ = 1.000 dm³. Jadi tangga panjang × 10, tangga luas × 10² = 100, dan tangga volume × 10³ = 1.000. Liter didefinisikan sama dengan 1 dm³, sehingga 1 m³ = 1.000 L.</p><h4>🧮 Mengapa satuan luas m²?</h4><p>Luas persegi panjang = panjang × lebar. Jika panjang 3 m dan lebar 2 m, maka luas = 3 m × 2 m = 6 m × m = <b>6 m²</b>. Satuan ikut dikalikan! Cara yang sama menghasilkan m³ untuk volume dan m/s untuk kecepatan (m dibagi s). Inilah sebabnya besaran turunan “mewarisi” satuan dari besaran pokok.</p>`,
rumus:[['v = s / t','kecepatan (m/s) = jarak (m) : waktu (s)'],['A = p × l','luas persegi panjang (m²)'],['V = p × l × t','volume balok (m³)'],['1 km/jam = 1/3,6 m/s','konversi kecepatan'],['tangga panjang, massa, liter: × 10 per anak tangga','turun dikali, naik dibagi'],['tangga luas: × 100 · tangga kubik: × 1.000','per anak tangga'],['1 L = 1 dm³ = 1.000 cm³','liter dan satuan kubik'],['1 mL = 1 cm³ = 1 cc','mililiter'],['1 m³ = 1 kL = 1.000 L','meter kubik ke liter'],['1 ha = 100 are = 10.000 m²','satuan luas tanah'],['1 ton = 10 kuintal = 1.000 kg','satuan massa besar'],['Hasil jangka sorong = SU + n × 0,01 cm','SU skala utama, n garis nonius yang berimpit']],
contoh:[
{s:'Sebuah motor melaju 72 km/jam. Berapa kecepatannya dalam m/s?', l:['Ubah jarak: 72 km = 72 × 1.000 m = 72.000 m.','Ubah waktu: 1 jam = 60 × 60 s = 3.600 s.','Bagi: 72.000 m : 3.600 s = 20 m/s.'], j:'72 km/jam = 20 m/s'},
{s:'Ibu membeli 2,5 liter minyak goreng. Berapa mL minyak tersebut?', l:['Pada tangga liter, dari L ke mL turun 3 anak tangga (L → dL → cL → mL).','Setiap turun dikali 10 → × 10 × 10 × 10 = × 1.000.','2,5 × 1.000 = 2.500.'], j:'2,5 L = 2.500 mL'},
{s:'Sebuah tandon air bervolume 1,5 m³. Berapa liter air yang dapat ditampung?', l:['Ingat: 1 m³ = 1.000 dm³ dan 1 dm³ = 1 L.','Jadi 1 m³ = 1.000 L.','1,5 × 1.000 = 1.500.'], j:'Tandon menampung 1.500 L'},
{s:'Akuarium berukuran 50 cm × 30 cm × 40 cm. Berapa liter air untuk mengisinya penuh?', l:['V = p × l × t = 50 × 30 × 40 = 60.000 cm³.','1 cm³ = 1 mL, jadi 60.000 cm³ = 60.000 mL.','Dari mL ke L naik 3 anak tangga → : 1.000 → 60 L.'], j:'Akuarium memuat 60 L air'},
{s:'Sawah Pak Budi seluas 3 hektare. Berapa m² luasnya?', l:['1 ha = 1 hm².','Dari hm² ke m² turun 2 anak tangga luas → × 100 × 100 = × 10.000.','3 × 10.000 = 30.000.'], j:'3 ha = 30.000 m²'},
{s:'Pada jangka sorong, skala utama menunjuk 2,3 cm dan garis nonius ke-4 berimpit. Berapa hasil pengukurannya?', l:['Ketelitian jangka sorong 0,01 cm.','Nilai nonius = 4 × 0,01 cm = 0,04 cm.','Hasil = 2,3 cm + 0,04 cm.'], j:'Hasil pengukuran = 2,34 cm'},
{s:'Sebuah balok berukuran 2 m × 50 cm × 30 cm. Berapa volumenya dalam m³?', l:['Samakan satuan: 50 cm = 0,5 m dan 30 cm = 0,3 m.','V = p × l × t = 2 × 0,5 × 0,3.','V = 0,3 m³.'], j:'Volume balok = 0,3 m³ (= 300 liter)'},
],
kuis:{bahas:'besaran pokok & turunan, satuan SI, tangga satuan panjang–massa–liter–luas–kubik, konversi liter ke cm³/m³, alat ukur dan ketelitiannya', soal:[
{q:'Kelompok berikut yang semuanya besaran pokok adalah…', o:['panjang, massa, waktu','panjang, luas, volume','massa, gaya, kecepatan','suhu, massa jenis, waktu'], a:0, p:'Luas, volume, gaya, kecepatan, dan massa jenis adalah besaran turunan karena dihitung dari besaran pokok. Hanya panjang, massa, dan waktu yang termasuk 7 besaran pokok.'},
{q:'Satuan SI untuk kuat arus listrik adalah…', o:['volt','ampere','ohm','watt'], a:1, p:'Kuat arus termasuk besaran pokok dengan satuan ampere (A). Volt adalah satuan tegangan, ohm satuan hambatan, watt satuan daya — semuanya besaran turunan.'},
{q:'36 km/jam sama dengan… m/s', o:['10','36','3,6','100'], a:0, p:'36 km = 36.000 m dan 1 jam = 3.600 s. Jadi 36.000 : 3.600 = 10 m/s. Cara cepat: 36 : 3,6 = 10.'},
{q:'2,5 liter sama dengan… mL', o:['2.500','250','25','25.000'], a:0, p:'Dari L ke mL turun 3 anak tangga liter (L → dL → cL → mL), setiap turun × 10, jadi × 1.000. 2,5 × 1.000 = 2.500 mL.'},
{q:'Bak mandi berisi 1,2 m³ air. Volume air itu sama dengan… liter', o:['1.200','120','12','12.000'], a:0, p:'1 m³ = 1.000 dm³ dan 1 dm³ = 1 L, sehingga 1 m³ = 1.000 L. 1,2 × 1.000 = 1.200 L.'},
{q:'500 cm³ sama dengan… liter', o:['0,5','5','50','0,05'], a:0, p:'1 cm³ = 1 mL, jadi 500 cm³ = 500 mL. Dari mL ke L naik 3 anak tangga → : 1.000 = 0,5 L.'},
{q:'4 m² sama dengan… cm²', o:['40.000','400','4.000','400.000'], a:0, p:'Pada tangga luas setiap anak tangga × 100. Dari m² ke cm² turun 2 anak tangga → × 100 × 100 = × 10.000. 4 × 10.000 = 40.000 cm².'},
{q:'Alat ukur panjang dengan ketelitian 0,01 mm adalah…', o:['mistar','jangka sorong','mikrometer sekrup','meteran gulung'], a:2, p:'Mistar teliti sampai 1 mm, jangka sorong 0,1 mm, dan mikrometer sekrup 0,01 mm. Jadi yang paling teliti (0,01 mm) adalah mikrometer sekrup.'},
{q:'Satuan gaya newton (N) setara dengan…', o:['kg·m/s²','kg·m/s','kg/m³','m/s²'], a:0, p:'Gaya = massa × percepatan (F = m·a). Satuannya kg × m/s² = kg·m/s². Satuan inilah yang diberi nama newton.'},
]}});

C({id:'f2', mapel:'fisika', no:2, ikon:'🧊', judul:'Zat & Wujudnya', lab:'massajenis',
ringkas:'Zat bisa berwujud padat, cair, atau gas tergantung susunan partikelnya. Wujud zat dapat berubah karena menyerap atau melepas kalor, dan setiap zat punya massa jenis yang khas.',
svg:`<svg class="ill" viewBox="0 0 320 168"><rect x="15" y="40" width="80" height="80" rx="8" fill="#fff" stroke="#2f7de1" stroke-width="2"/>${[0,1,2,3].map(r=>[0,1,2,3].map(c=>`<circle cx="${30+c*17}" cy="${55+r*17}" r="7" fill="#2f7de1"/>`).join('')).join('')}<rect x="120" y="40" width="80" height="80" rx="8" fill="#fff" stroke="#2f7de1" stroke-width="2"/>${[[132,95],[150,100],[168,96],[186,104],[140,110],[160,112],[178,88],[132,78],[158,82],[188,74]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="7" fill="#60a5fa"/>`).join('')}<rect x="225" y="40" width="80" height="80" rx="8" fill="#fff" stroke="#2f7de1" stroke-width="2"/>${[[240,55],[285,62],[262,92],[238,108],[292,104]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="7" fill="#bfdbfe" stroke="#60a5fa"/>`).join('')}<text x="55" y="140" text-anchor="middle" font-size="13" font-weight="700" fill="#16323f">Padat</text><text x="160" y="140" text-anchor="middle" font-size="13" font-weight="700" fill="#16323f">Cair</text><text x="265" y="140" text-anchor="middle" font-size="13" font-weight="700" fill="#16323f">Gas</text><path d="M98 30 Q107 18 117 30" fill="none" stroke="#ef4444" stroke-width="2" marker-end="url(#a1)"/><path d="M203 30 Q212 18 222 30" fill="none" stroke="#ef4444" stroke-width="2" marker-end="url(#a1)"/><defs><marker id="a1" markerWidth="8" markerHeight="8" refX="4" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="#ef4444"/></marker></defs><text x="160" y="162" text-anchor="middle" font-size="11" fill="#ef4444">dipanaskan → partikel makin renggang & cepat</text></svg>`,
sesi:[
{j:'Tiga wujud zat', h:`<div class="tbl"><table><tr><th></th><th>Padat</th><th>Cair</th><th>Gas</th></tr><tr><td>Susunan partikel</td><td>sangat rapat & teratur</td><td>agak renggang</td><td>sangat renggang</td></tr><tr><td>Gerak partikel</td><td>bergetar di tempat</td><td>dapat berpindah tempat</td><td>bergerak bebas & cepat</td></tr><tr><td>Gaya tarik antarpartikel</td><td>sangat kuat</td><td>lemah</td><td>sangat lemah</td></tr><tr><td>Bentuk</td><td>tetap</td><td>mengikuti wadah</td><td>mengikuti wadah</td></tr><tr><td>Volume</td><td>tetap</td><td>tetap</td><td>berubah (memenuhi ruang)</td></tr></table></div><p>Karena partikel gas sangat renggang, gas mudah dimampatkan — itulah sebabnya ban bisa dipompa.</p>`},
{j:'Perubahan wujud zat', h:`<ul><li><b>Mencair</b> (padat → cair): es batu meleleh — <i>menyerap kalor</i></li><li><b>Membeku</b> (cair → padat): air di freezer — <i>melepas kalor</i></li><li><b>Menguap</b> (cair → gas): jemuran mengering — <i>menyerap kalor</i></li><li><b>Mengembun</b> (gas → cair): embun di daun pagi hari — <i>melepas kalor</i></li><li><b>Menyublim</b> (padat → gas): kapur barus mengecil — <i>menyerap kalor</i></li><li><b>Mengkristal / deposisi</b> (gas → padat): terbentuknya salju di awan — <i>melepas kalor</i></li></ul><div class="note">🧠 Trik: perubahan menuju wujud yang partikelnya lebih renggang (padat → cair → gas) selalu <b>menyerap</b> kalor. Kebalikannya <b>melepas</b> kalor.</div>`},
{j:'Massa jenis', h:`<p>Massa jenis (ρ, dibaca “rho”) menunjukkan seberapa rapat massa suatu zat dalam setiap satuan volume.</p><div class="f">ρ = m / V &nbsp;&nbsp; (kg/m³ atau g/cm³)</div><p>1 g/cm³ = 1.000 kg/m³. Massa jenis adalah <b>ciri khas zat</b>: sebongkah kecil emas dan sebatang besar emas punya massa jenis yang sama.</p><div class="tbl"><table><tr><th>Zat</th><th>ρ (kg/m³)</th></tr><tr><td>Minyak goreng</td><td>±800</td></tr><tr><td>Es</td><td>920</td></tr><tr><td>Air</td><td>1.000</td></tr><tr><td>Aluminium</td><td>2.700</td></tr><tr><td>Besi</td><td>7.900</td></tr><tr><td>Raksa</td><td>13.600</td></tr><tr><td>Emas</td><td>19.300</td></tr></table></div>`},
{j:'Terapung, melayang, tenggelam', h:`<p>Bandingkan massa jenis benda (ρb) dengan massa jenis zat cair (ρc):</p><ul><li>ρb &lt; ρc → <b>terapung</b> (kayu, es di air)</li><li>ρb = ρc → <b>melayang</b> (telur dalam air garam yang pas)</li><li>ρb &gt; ρc → <b>tenggelam</b> (batu, paku)</li></ul><p>Kapal dari besi bisa terapung karena bentuknya berongga berisi udara, sehingga massa jenis rata-rata kapal lebih kecil daripada air laut.</p><div class="note">🧊 Es terapung dengan ±92% bagian tercelup, karena 920/1.000 = 0,92. Itu sebabnya puncak gunung es hanya sebagian kecil!</div>`},
{j:'Kohesi, adhesi & kapilaritas', h:`<p><b>Kohesi</b> = gaya tarik antarpartikel sejenis. <b>Adhesi</b> = gaya tarik antarpartikel tak sejenis.</p><ul><li>Air membasahi kaca karena adhesi air–kaca &gt; kohesi air → permukaan air di tabung <b>cekung</b> (meniskus cekung).</li><li>Raksa tidak membasahi kaca karena kohesi raksa &gt; adhesi → permukaan <b>cembung</b>.</li></ul><p><b>Kapilaritas</b> adalah naik/turunnya zat cair dalam pipa sempit. Contoh: minyak naik pada sumbu kompor, air naik dari akar ke daun, tisu menyerap air, dinding rumah lembap karena air naik dari tanah.</p>`},
],
penemuan:`<h4>🛁 “Eureka!” — Archimedes dan mahkota raja</h4><p>Sekitar abad ke-3 SM, Raja Hieron II dari Syracuse curiga mahkota emasnya dicampur perak oleh tukang emas. Ia meminta <b>Archimedes</b> membuktikannya tanpa merusak mahkota.</p><p>Saat masuk ke bak mandi, Archimedes melihat air tumpah. Ia sadar: <b>volume benda yang tercelup sama dengan volume air yang dipindahkan</b>. Dengan cara ini, volume benda berbentuk rumit seperti mahkota bisa diukur!</p><div class="tl"><div><b>Langkah 1</b> — Siapkan emas murni yang massanya sama dengan mahkota.</div><div><b>Langkah 2</b> — Celupkan keduanya bergantian ke wadah penuh air dan ukur air yang tumpah.</div><div><b>Langkah 3</b> — Mahkota menumpahkan air <b>lebih banyak</b> → volumenya lebih besar → dengan massa sama, massa jenisnya lebih kecil → ada logam lain yang lebih ringan (perak) di dalamnya.</div></div><h4>🧮 Lahirnya rumus ρ = m/V</h4><p>Dua benda bisa bermassa sama tetapi volumenya berbeda (1 kg kapas vs 1 kg besi). Untuk membandingkan “kepadatan” secara adil, kita hitung massa untuk setiap 1 satuan volume, yaitu massa dibagi volume. Hasilnya selalu sama untuk zat yang sama, sehingga bisa dipakai sebagai “sidik jari” zat.</p>`,
rumus:[['ρ = m / V','massa jenis = massa : volume'],['m = ρ × V','mencari massa'],['V = m / ρ','mencari volume'],['V benda = V air naik','mengukur volume benda tak beraturan dengan gelas ukur']],
contoh:[
{s:'Sebuah batu bermassa 300 g dimasukkan ke gelas ukur. Permukaan air naik dari 50 mL menjadi 150 mL. Berapa massa jenis batu?', l:['Volume batu = 150 − 50 = 100 mL = 100 cm³.','ρ = m / V = 300 g / 100 cm³.','ρ = 3 g/cm³ = 3.000 kg/m³.'], j:'Massa jenis batu = 3 g/cm³ (3.000 kg/m³)'},
{s:'Kayu dengan massa jenis 600 kg/m³ dimasukkan ke air. Apa yang terjadi, dan berapa bagian yang tercelup?', l:['Bandingkan: ρ kayu = 600 kg/m³ < ρ air = 1.000 kg/m³ → terapung.','Bagian tercelup = ρ benda / ρ air = 600/1.000 = 0,6.'], j:'Kayu terapung dengan 60% volumenya tercelup'},
{s:'Berapa massa 2 liter minyak goreng yang massa jenisnya 800 kg/m³?', l:['Ubah volume: 2 liter = 2 dm³ = 0,002 m³.','m = ρ × V = 800 × 0,002.'], j:'Massa minyak = 1,6 kg'},
],
kuis:{bahas:'sifat partikel tiap wujud, nama perubahan wujud & kalornya, menghitung massa jenis, serta terapung–melayang–tenggelam dan kapilaritas', soal:[
{q:'Kapur barus di lemari lama-kelamaan habis. Peristiwa ini disebut…', o:['menguap','menyublim','mencair','mengembun'], a:1, p:'Kapur barus berubah langsung dari padat menjadi gas tanpa mencair lebih dulu. Perubahan padat → gas disebut menyublim.'},
{q:'Perubahan wujud yang melepaskan kalor adalah…', o:['mencair','menguap','membeku','menyublim'], a:2, p:'Membeku (cair → padat) membuat partikel lebih rapat, sehingga energi dilepas. Mencair, menguap, dan menyublim justru menyerap kalor.'},
{q:'Benda bermassa 200 g dan bervolume 50 cm³ memiliki massa jenis…', o:['4 g/cm³','0,25 g/cm³','250 g/cm³','10.000 g/cm³'], a:0, p:'ρ = m / V = 200 g / 50 cm³ = 4 g/cm³ (= 4.000 kg/m³).'},
{q:'Benda dengan massa jenis 1.200 kg/m³ dimasukkan ke air (1.000 kg/m³). Benda akan…', o:['terapung','melayang','tenggelam','menguap'], a:2, p:'Karena ρ benda (1.200) lebih besar daripada ρ air (1.000), benda tenggelam.'},
{q:'Minyak tanah naik melalui sumbu kompor. Ini contoh…', o:['kohesi','kapilaritas','konveksi','sublimasi'], a:1, p:'Naiknya zat cair melalui celah sempit (pori-pori sumbu) disebut kapilaritas, terjadi karena adhesi zat cair dengan dinding celah.'},
]}});

C({id:'f3', mapel:'fisika', no:3, ikon:'🌡️', judul:'Suhu & Kalor', lab:'suhu',
ringkas:'Suhu menyatakan derajat panas suatu benda, sedangkan kalor adalah energi panas yang berpindah. Pelajari skala termometer, pemuaian, perpindahan kalor, dan Asas Black.',
svg:`<svg class="ill" viewBox="0 0 320 168">${[['C',0,100,'#ef4444'],['R',0,80,'#f97316'],['F',32,212,'#2f7de1'],['K',273,373,'#8b5cf6']].map(([n,a,b,c],i)=>{const x=50+i*75;return `<rect x="${x-9}" y="18" width="18" height="110" rx="9" fill="#fff" stroke="#94a3b8" stroke-width="2"/><rect x="${x-4}" y="60" width="8" height="70" fill="${c}"/><circle cx="${x}" cy="138" r="14" fill="${c}"/><text x="${x+14}" y="26" font-size="10" fill="#475569">${b}</text><text x="${x+14}" y="122" font-size="10" fill="#475569">${a}</text><text x="${x}" y="164" text-anchor="middle" font-size="13" font-weight="700" fill="${c}">°${n}</text>`}).join('')}</svg>`,
sesi:[
{j:'Suhu dan termometer', h:`<p><b>Suhu</b> adalah derajat panas atau dinginnya benda. Indra peraba tidak bisa diandalkan (air hangat terasa panas bagi tangan yang dingin), maka kita memakai <b>termometer</b>.</p><p>Termometer zat cair bekerja berdasarkan <b>pemuaian</b>: makin panas, zat cair di pipa kapiler makin memuai dan naik. Raksa sering dipakai karena mengkilap (mudah dibaca), memuai teratur, tidak membasahi dinding kaca, dan rentang ukurnya lebar (−39°C sampai 357°C). Alkohol dipakai untuk suhu sangat dingin karena membeku pada −114°C.</p><p>Jenis termometer: termometer laboratorium, klinis (36–42°C, ada lekukan agar raksa tidak langsung turun), ruangan, digital, dan inframerah.</p>`},
{j:'Skala suhu: C, R, F, K', h:`<p>Setiap skala memakai dua <b>titik tetap</b>: titik lebur es (bawah) dan titik didih air (atas) pada tekanan 1 atm.</p><div class="tbl"><table><tr><th>Skala</th><th>Titik bawah</th><th>Titik atas</th><th>Jumlah skala</th></tr><tr><td>Celcius</td><td>0</td><td>100</td><td>100</td></tr><tr><td>Reamur</td><td>0</td><td>80</td><td>80</td></tr><tr><td>Fahrenheit</td><td>32</td><td>212</td><td>180</td></tr><tr><td>Kelvin</td><td>273</td><td>373</td><td>100</td></tr></table></div><div class="f">C : R : (F − 32) : (K − 273) = 5 : 4 : 9 : 5</div><p>Kelvin disebut skala mutlak karena 0 K (−273°C) adalah suhu terendah yang mungkin — partikel hampir berhenti bergerak.</p>`},
{j:'Pemuaian', h:`<p>Hampir semua zat memuai saat dipanaskan dan menyusut saat didinginkan, karena partikelnya bergerak lebih kuat dan saling menjauh.</p><div class="f">ΔL = L₀ × α × ΔT</div><p>α (koefisien muai panjang) berbeda untuk tiap bahan. Contoh di kehidupan:</p><ul><li>Celah pada sambungan rel kereta dan jembatan.</li><li>Kabel listrik dipasang kendur saat siang.</li><li>Bimetal (dua logam berbeda koefisien muainya) melengkung saat panas → dipakai di setrika, alarm kebakaran, dan lampu sein.</li><li>Memasang ring besi pada roda pedati: ring dipanaskan agar memuai, lalu didinginkan sehingga menjepit kuat.</li></ul><div class="note">🧊 <b>Anomali air</b>: dari 0°C ke 4°C air justru menyusut. Massa jenis air terbesar pada 4°C, sehingga di danau beku air di dasar tetap 4°C dan ikan bisa bertahan hidup.</div>`},
{j:'Kalor dan perubahan suhu/wujud', h:`<p><b>Kalor</b> (Q) adalah energi panas yang berpindah dari benda bersuhu tinggi ke benda bersuhu rendah. Satuannya joule (J); 1 kalori = 4,2 J.</p><div class="f">Q = m × c × ΔT &nbsp;(menaikkan/menurunkan suhu)</div><div class="f">Q = m × L &nbsp;(mengubah wujud, suhu tetap)</div><p>c = kalor jenis (J/kg°C) — kalor untuk menaikkan 1 kg zat sebesar 1°C. Air punya kalor jenis besar (4.200 J/kg°C), jadi air lambat panas dan lambat dingin — itulah sebabnya laut menjaga iklim pantai tetap sejuk.</p><p>L = kalor laten: kalor lebur es 336.000 J/kg, kalor uap air 2.260.000 J/kg. Selama berubah wujud, suhu <b>tidak</b> naik meski terus dipanaskan.</p>`},
{j:'Perpindahan kalor', h:`<ul><li><b>Konduksi</b>: kalor merambat lewat zat tanpa perpindahan partikel. Terjadi pada zat padat, terutama logam (konduktor). Contoh: ujung sendok di gelas teh panas ikut panas. Kayu, plastik, dan kain adalah isolator.</li><li><b>Konveksi</b>: kalor berpindah bersama aliran partikel pada zat cair dan gas. Contoh: air mendidih bergolak, angin darat dan angin laut, cerobong asap.</li><li><b>Radiasi</b>: kalor berpindah tanpa medium dalam bentuk gelombang. Contoh: panas matahari sampai ke Bumi, hangatnya api unggun. Permukaan hitam & kusam menyerap radiasi paling baik.</li></ul><div class="note">🧃 <b>Termos</b> mencegah ketiganya: ruang hampa (cegah konduksi & konveksi), dinding mengkilap (cegah radiasi), tutup rapat.</div>`},
{j:'Asas Black', h:`<p>Jika dua zat berbeda suhu dicampur, zat panas melepas kalor dan zat dingin menerima kalor sampai suhunya sama (suhu campuran, Tc).</p><div class="f">Q lepas = Q terima → m₁ c₁ (T₁ − Tc) = m₂ c₂ (Tc − T₂)</div><p>Contoh sehari-hari: menambah air dingin ke air mendidih untuk mandi, atau es batu dalam teh.</p>`},
],
penemuan:`<h4>🌡️ Sejarah skala suhu</h4><div class="tl"><div><b>1593</b> — Galileo Galilei membuat termoskop: udara dalam bola kaca memuai dan mendorong air. Belum ada angka.</div><div><b>1724</b> — Daniel Gabriel Fahrenheit memakai raksa. Titik 0 dari campuran es, air, dan garam (suhu terdingin yang bisa ia buat); air membeku di 32°F, mendidih di 212°F.</div><div><b>1730</b> — René de Réaumur membagi rentang beku–didih air menjadi 80 bagian.</div><div><b>1742</b> — Anders Celsius membagi rentang yang sama menjadi 100 bagian (awalnya terbalik: 100 untuk beku!). Skala dibalik setelah ia wafat.</div><div><b>1848</b> — Lord Kelvin mengusulkan skala mutlak yang dimulai dari nol mutlak (−273,15°C).</div></div>
<h4>🧮 Menurunkan rumus konversi</h4><p>Bayangkan dua termometer di bejana yang sama. Posisi raksanya “sama jauh” secara relatif dari titik bawah ke titik atas:</p><div class="f">(C − 0)/(100 − 0) = (F − 32)/(212 − 32) → C/100 = (F − 32)/180</div><p>Sederhanakan dengan membagi penyebut dengan 20: <b>C/5 = (F − 32)/9</b>, sehingga <b>F = ⁹⁄₅C + 32</b>. Dengan cara serupa diperoleh C : R = 100 : 80 = 5 : 4 dan K = C + 273.</p>
<h4>🔥 Joseph Black dan kalor (1760-an)</h4><p>Ilmuwan Skotlandia <b>Joseph Black</b> memanaskan es dan melihat suhunya tetap 0°C sampai seluruh es mencair. Ia menyimpulkan ada kalor “tersembunyi” (laten) untuk mengubah wujud. Ia juga mencampur air panas dan dingin dan menemukan bahwa kalor yang dilepas sama dengan kalor yang diterima — kini disebut <b>Asas Black</b>. Dari percobaannya pula terlihat bahwa kalor sebanding dengan massa (m), kenaikan suhu (ΔT), dan bergantung jenis zat (c): <b>Q = m·c·ΔT</b>.</p>`,
rumus:[['C : R : (F−32) : (K−273) = 5 : 4 : 9 : 5','perbandingan skala suhu'],['F = ⁹⁄₅ C + 32','Celcius ke Fahrenheit'],['K = C + 273','Celcius ke Kelvin'],['Q = m · c · ΔT','kalor untuk mengubah suhu'],['Q = m · L','kalor untuk mengubah wujud'],['m₁c₁(T₁ − Tc) = m₂c₂(Tc − T₂)','Asas Black'],['ΔL = L₀ · α · ΔT','pemuaian panjang']],
contoh:[
{s:'Ubah 50°C ke skala Reamur, Fahrenheit, dan Kelvin.', l:['R = ⁴⁄₅ × 50 = 40°R.','F = ⁹⁄₅ × 50 + 32 = 90 + 32 = 122°F.','K = 50 + 273 = 323 K.'], j:'50°C = 40°R = 122°F = 323 K'},
{s:'Berapa kalor untuk memanaskan 2 kg air dari 20°C menjadi 70°C? (c air = 4.200 J/kg°C)', l:['ΔT = 70 − 20 = 50°C.','Q = m × c × ΔT = 2 × 4.200 × 50.','Q = 420.000 J.'], j:'Q = 420.000 J = 420 kJ'},
{s:'1 kg air 80°C dicampur dengan 1 kg air 20°C. Berapa suhu akhirnya?', l:['Q lepas = Q terima → 1 × c × (80 − Tc) = 1 × c × (Tc − 20).','c sama dan massa sama, jadi 80 − Tc = Tc − 20.','100 = 2Tc → Tc = 50°C.'], j:'Suhu campuran = 50°C'},
{s:'Rel besi sepanjang 10 m (α = 0,000012/°C) memanas dari 25°C ke 75°C. Berapa pertambahan panjangnya?', l:['ΔT = 50°C.','ΔL = L₀ × α × ΔT = 10 × 0,000012 × 50.','ΔL = 0,006 m.'], j:'Rel memanjang 0,006 m = 6 mm'},
],
kuis:{bahas:'konversi skala termometer, menghitung kalor (Q = m·c·ΔT), Asas Black, pemuaian, dan jenis perpindahan kalor', soal:[
{q:'Suhu 20°C sama dengan…°F', o:['68','36','52','4'], a:0, p:'F = ⁹⁄₅ × C + 32 = ⁹⁄₅ × 20 + 32 = 36 + 32 = 68°F.'},
{q:'Suhu 300 K sama dengan…°C', o:['27','573','−27','30'], a:0, p:'C = K − 273 = 300 − 273 = 27°C.'},
{q:'Kalor untuk menaikkan suhu 0,5 kg air dari 30°C menjadi 50°C (c = 4.200 J/kg°C) adalah…', o:['42.000 J','4.200 J','84.000 J','21.000 J'], a:0, p:'Q = m·c·ΔT = 0,5 × 4.200 × (50 − 30) = 0,5 × 4.200 × 20 = 42.000 J.'},
{q:'Sambungan rel kereta api diberi celah agar…', o:['mengurangi gesekan','memberi ruang untuk pemuaian','kereta melaju lebih cepat','menghemat besi'], a:1, p:'Saat siang rel memanas dan memuai. Tanpa celah, rel akan saling mendorong dan melengkung.'},
{q:'Panas matahari sampai ke Bumi melalui…', o:['konduksi','konveksi','radiasi','isolasi'], a:2, p:'Di antara Matahari dan Bumi ada ruang hampa (tanpa medium). Hanya radiasi yang dapat memindahkan kalor tanpa medium.'},
]}});

C({id:'f4', mapel:'fisika', no:4, ikon:'🚀', judul:'Gerak, Gaya & Tekanan', lab:'glbb',
ringkas:'Benda bergerak lurus beraturan (GLB) atau berubah beraturan (GLBB). Hukum Newton menjelaskan hubungan gaya dan gerak, sedangkan tekanan menjelaskan pisau tajam, dongkrak hidrolik, hingga kapal laut.',
svg:`<svg class="ill" viewBox="0 0 320 168"><rect x="0" y="118" width="320" height="22" fill="#cbd5e1"/><line x1="0" y1="129" x2="320" y2="129" stroke="#fff" stroke-dasharray="14 10" stroke-width="2"/><text x="20" y="116" font-size="36">🚗</text><line x1="72" y1="92" x2="132" y2="92" stroke="#16a34a" stroke-width="4" marker-end="url(#a2)"/><text x="100" y="84" text-anchor="middle" font-size="12" fill="#16a34a" font-weight="700">v</text><text x="170" y="116" font-size="36" opacity=".55">🚗</text><line x1="222" y1="92" x2="312" y2="92" stroke="#16a34a" stroke-width="4" marker-end="url(#a2)"/><text x="306" y="84" text-anchor="end" font-size="12" fill="#16a34a" font-weight="700">v makin besar</text><defs><marker id="a2" markerWidth="8" markerHeight="8" refX="4" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="#16a34a"/></marker></defs><text x="20" y="30" font-size="13" font-weight="700" fill="#16323f">F = m · a</text><text x="20" y="50" font-size="12" fill="#475569">s = v₀t + ½at²</text><text x="200" y="30" font-size="12" fill="#475569">P = F / A</text><text x="200" y="50" font-size="12" fill="#475569">Ph = ρ g h</text></svg>`,
sesi:[
{j:'Jarak, perpindahan, kelajuan, kecepatan', h:`<p><b>Jarak</b> adalah panjang seluruh lintasan (besaran skalar). <b>Perpindahan</b> adalah perubahan posisi dari awal ke akhir, lengkap dengan arah (vektor).</p><p>Contoh: Rina berjalan 4 m ke timur lalu 3 m ke utara. Jaraknya 7 m, tetapi perpindahannya √(4² + 3²) = 5 m ke arah timur laut.</p><div class="f">kelajuan = jarak / waktu &nbsp;|&nbsp; kecepatan = perpindahan / waktu</div><p>Speedometer motor menunjukkan kelajuan sesaat.</p>`},
{j:'Gerak Lurus Beraturan (GLB)', h:`<p>GLB = gerak pada lintasan lurus dengan <b>kecepatan tetap</b> (percepatan nol). Dalam selang waktu yang sama, jarak yang ditempuh selalu sama.</p><div class="f">s = v × t</div><p>Grafik v–t berupa garis mendatar; grafik s–t berupa garis lurus miring. Contoh: kereta melaju stabil di rel lurus, mobil dengan cruise control di jalan tol.</p>`},
{j:'Gerak Lurus Berubah Beraturan (GLBB)', h:`<p>GLBB = gerak lurus dengan <b>percepatan tetap</b>. Kecepatan bertambah atau berkurang secara teratur.</p><div class="f">vₜ = v₀ + a·t &nbsp;|&nbsp; s = v₀·t + ½·a·t² &nbsp;|&nbsp; vₜ² = v₀² + 2·a·s</div><ul><li><b>Dipercepat</b> (a positif): buah kelapa jatuh, motor mulai melaju.</li><li><b>Diperlambat</b> (a negatif): mobil direm, bola dilempar ke atas.</li></ul><p>Benda jatuh bebas mengalami percepatan gravitasi g ≈ 9,8 m/s² (sering dibulatkan 10 m/s²).</p>`},
{j:'Hukum Newton', h:`<ul><li><b>Hukum I (inersia)</b>: jika resultan gaya nol, benda diam tetap diam dan benda bergerak tetap bergerak lurus beraturan. Contoh: penumpang terdorong ke depan saat bus mengerem mendadak; kain ditarik cepat dari bawah gelas, gelas tetap di tempat.</li><li><b>Hukum II</b>: percepatan sebanding dengan resultan gaya dan berbanding terbalik dengan massa. <span class="f" style="display:inline-block;margin:4px 0">F = m × a</span> Mendorong troli kosong lebih mudah daripada troli penuh.</li><li><b>Hukum III (aksi–reaksi)</b>: setiap aksi menimbulkan reaksi yang sama besar dan berlawanan arah. Contoh: mendayung perahu, roket menyemburkan gas ke bawah lalu terdorong ke atas, telapak kaki mendorong lantai ke belakang saat berjalan.</li></ul><p><b>Berat</b> adalah gaya gravitasi: w = m × g. Massa 50 kg di Bumi beratnya ±500 N; di Bulan (g ≈ 1,6 m/s²) hanya ±80 N, tetapi massanya tetap 50 kg.</p>`},
{j:'Tekanan zat padat', h:`<div class="f">P = F / A &nbsp;(N/m² = pascal, Pa)</div><p>Tekanan makin besar jika gaya makin besar atau luas bidang tekan makin kecil.</p><ul><li>Pisau dan paku dibuat runcing → A kecil → P besar → mudah menembus.</li><li>Sepatu salju, ban truk lebar, pondasi bangunan lebar → A besar → P kecil → tidak mudah amblas.</li></ul>`},
{j:'Tekanan zat cair: hidrostatis, Pascal, Archimedes', h:`<p><b>Tekanan hidrostatis</b> bergantung pada kedalaman, bukan bentuk wadah:</p><div class="f">Ph = ρ × g × h</div><p>Karena itu dinding bendungan dibuat makin tebal ke bawah, dan penyelam merasakan telinga sakit di kedalaman.</p><p><b>Hukum Pascal</b>: tekanan pada zat cair di ruang tertutup diteruskan sama besar ke segala arah.</p><div class="f">F₁ / A₁ = F₂ / A₂</div><p>Penerapan: dongkrak hidrolik, rem hidrolik, kursi pasien dokter gigi, mesin pres.</p><p><b>Hukum Archimedes</b>: benda yang tercelup menerima gaya ke atas sebesar berat zat cair yang dipindahkan.</p><div class="f">Fa = ρ cair × g × V tercelup</div><p>Penerapan: kapal laut, kapal selam (mengatur air di tangki pemberat), balon udara, hidrometer.</p>`},
],
penemuan:`<h4>⚖️ Galileo dan bola di bidang miring</h4><p>Pada awal 1600-an, belum ada jam yang cukup akurat untuk mengukur benda jatuh. <b>Galileo Galilei</b> “memperlambat” gerak jatuh dengan menggelindingkan bola di bidang miring panjang, lalu mengukur waktu memakai <b>jam air</b> (menimbang air yang menetes).</p><p>Ia menemukan: jarak yang ditempuh dalam 1, 2, 3, 4 satuan waktu berbanding <b>1 : 4 : 9 : 16</b> — yaitu sebanding dengan kuadrat waktu (s ∝ t²). Inilah cikal bakal rumus GLBB.</p><h4>🧮 Menurunkan rumus GLBB</h4><div class="tl"><div><b>Definisi percepatan</b>: a = (vₜ − v₀)/t → <b>vₜ = v₀ + a·t</b>.</div><div><b>Jarak = luas di bawah grafik v–t</b>. Grafiknya berbentuk trapesium dengan sisi sejajar v₀ dan vₜ, tinggi t.</div><div>s = ½ (v₀ + vₜ) × t = ½ (v₀ + v₀ + a·t) × t = <b>v₀·t + ½·a·t²</b>. Jika v₀ = 0, maka s = ½at² → sebanding t², persis temuan Galileo!</div></div>
<h4>🍎 Isaac Newton (1687)</h4><p>Dalam buku <i>Principia</i>, Newton merangkum tiga hukum gerak dan hukum gravitasi. Hukum I sebenarnya mengembangkan gagasan Galileo bahwa benda cenderung mempertahankan geraknya.</p><h4>💧 Menurunkan Ph = ρgh dan hukum Pascal</h4><p>Bayangkan kolom air setinggi h dengan alas luas A. Massanya m = ρ × V = ρ × A × h, beratnya w = ρ·A·h·g. Tekanan = berat / luas = ρ·A·h·g / A = <b>ρ·g·h</b> — luas A hilang, jadi tekanan hanya bergantung kedalaman.</p><p><b>Blaise Pascal</b> (abad ke-17) menunjukkan bahwa tekanan pada zat cair tertutup diteruskan merata. Karena P₁ = P₂, maka F₁/A₁ = F₂/A₂: gaya kecil pada pengisap kecil bisa mengangkat beban besar pada pengisap besar.</p>`,
rumus:[['s = v · t','GLB'],['vₜ = v₀ + a · t','GLBB: kecepatan akhir'],['s = v₀ · t + ½ · a · t²','GLBB: jarak'],['vₜ² = v₀² + 2 · a · s','GLBB tanpa waktu'],['F = m · a','Hukum II Newton'],['w = m · g','berat benda'],['P = F / A','tekanan zat padat'],['Ph = ρ · g · h','tekanan hidrostatis'],['F₁/A₁ = F₂/A₂','Hukum Pascal'],['Fa = ρ · g · V','gaya apung Archimedes']],
contoh:[
{s:'Mobil mula-mula diam lalu dipercepat 2 m/s² selama 5 s. Berapa kecepatan akhir dan jarak tempuhnya?', l:['Diketahui v₀ = 0, a = 2 m/s², t = 5 s.','vₜ = v₀ + a·t = 0 + 2 × 5 = 10 m/s.','s = v₀·t + ½·a·t² = 0 + ½ × 2 × 25 = 25 m.'], j:'vₜ = 10 m/s dan s = 25 m'},
{s:'Gaya berapa yang dibutuhkan untuk mempercepat mobil 1.000 kg sebesar 3 m/s²?', l:['Gunakan Hukum II Newton: F = m × a.','F = 1.000 × 3.'], j:'F = 3.000 N'},
{s:'Ikan berada 5 m di bawah permukaan air. Berapa tekanan hidrostatisnya? (ρ air = 1.000 kg/m³, g = 10 m/s²)', l:['Ph = ρ × g × h.','Ph = 1.000 × 10 × 5.'], j:'Ph = 50.000 Pa'},
{s:'Dongkrak hidrolik memiliki A₁ = 10 cm² dan A₂ = 1.000 cm². Berapa gaya F₁ untuk mengangkat mobil 20.000 N?', l:['F₁/A₁ = F₂/A₂ → F₁ = F₂ × A₁ / A₂.','F₁ = 20.000 × 10 / 1.000.'], j:'F₁ = 200 N — gaya 100 kali lebih kecil!'},
{s:'Balok bervolume 0,002 m³ tercelup seluruhnya dalam air. Berapa gaya apungnya?', l:['Fa = ρ air × g × V.','Fa = 1.000 × 10 × 0,002.'], j:'Fa = 20 N'},
],
kuis:{bahas:'GLB dan GLBB, tiga Hukum Newton, tekanan zat padat, tekanan hidrostatis, Hukum Pascal, dan Hukum Archimedes', soal:[
{q:'Motor bergerak lurus beraturan 20 m/s selama 30 s. Jarak tempuhnya…', o:['600 m','50 m','1,5 m','6.000 m'], a:0, p:'GLB: s = v × t = 20 × 30 = 600 m.'},
{q:'Penumpang terdorong ke depan saat bus mengerem mendadak. Ini contoh Hukum Newton…', o:['I','II','III','gravitasi'], a:0, p:'Tubuh penumpang cenderung mempertahankan geraknya (inersia) saat bus berhenti. Itulah Hukum I Newton.'},
{q:'Gaya 50 N bekerja pada benda 10 kg. Percepatannya…', o:['5 m/s²','500 m/s²','0,2 m/s²','60 m/s²'], a:0, p:'a = F / m = 50 / 10 = 5 m/s².'},
{q:'Tekanan hidrostatis pada kedalaman 2 m di dalam air (ρ = 1.000 kg/m³, g = 10 m/s²) adalah…', o:['20.000 Pa','2.000 Pa','200 Pa','20 Pa'], a:0, p:'Ph = ρ·g·h = 1.000 × 10 × 2 = 20.000 Pa.'},
{q:'Dongkrak hidrolik bekerja berdasarkan hukum…', o:['Archimedes','Pascal','Newton III','Boyle'], a:1, p:'Tekanan pada pengisap kecil diteruskan sama besar ke pengisap besar melalui zat cair tertutup — Hukum Pascal.'},
]}});

C({id:'f5', mapel:'fisika', no:5, ikon:'⚙️', judul:'Usaha, Energi & Pesawat Sederhana', lab:'tuas',
ringkas:'Usaha terjadi jika gaya memindahkan benda. Energi tidak dapat diciptakan atau dimusnahkan, hanya berubah bentuk. Pesawat sederhana membuat pekerjaan terasa lebih ringan.',
svg:`<svg class="ill" viewBox="0 0 320 168"><line x1="30" y1="96" x2="290" y2="74" stroke="#92400e" stroke-width="9" stroke-linecap="round"/><polygon points="100,92 80,132 120,132" fill="#64748b"/><rect x="18" y="58" width="44" height="36" rx="4" fill="#f97316"/><text x="40" y="81" text-anchor="middle" font-size="12" fill="#fff" font-weight="700">beban</text><line x1="282" y1="24" x2="282" y2="66" stroke="#16a34a" stroke-width="4" marker-end="url(#a3)"/><text x="282" y="18" text-anchor="middle" font-size="12" font-weight="700" fill="#16a34a">kuasa</text><text x="100" y="150" text-anchor="middle" font-size="12" fill="#475569">titik tumpu</text><text x="60" y="122" font-size="11" fill="#6b7f88">Lb</text><text x="190" y="110" font-size="11" fill="#6b7f88">Lk</text><text x="200" y="150" font-size="13" font-weight="700" fill="#16323f">w × Lb = F × Lk</text><defs><marker id="a3" markerWidth="8" markerHeight="8" refX="4" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="#16a34a"/></marker></defs></svg>`,
sesi:[
{j:'Usaha', h:`<p>Dalam fisika, <b>usaha</b> (W) dilakukan jika sebuah gaya membuat benda berpindah searah gaya.</p><div class="f">W = F × s &nbsp; (joule, J)</div><p>Usaha bernilai <b>nol</b> jika benda tidak berpindah (mendorong tembok seharian tetap W = 0!) atau jika gaya tegak lurus perpindahan (membawa tas sambil berjalan mendatar). Jika gaya berlawanan arah perpindahan (gaya gesek), usahanya negatif.</p>`},
{j:'Bentuk-bentuk energi', h:`<p><b>Energi</b> adalah kemampuan untuk melakukan usaha. Bentuknya: energi kinetik (gerak), potensial (kedudukan), kimia (makanan, baterai, bensin), listrik, panas, cahaya, bunyi, dan nuklir.</p><div class="tbl"><table><tr><th>Alat / peristiwa</th><th>Perubahan energi</th></tr><tr><td>Setrika listrik</td><td>listrik → panas</td></tr><tr><td>Aki / baterai</td><td>kimia → listrik</td></tr><tr><td>Panel surya</td><td>cahaya → listrik</td></tr><tr><td>PLTA</td><td>potensial air → kinetik → listrik</td></tr><tr><td>Tubuh berlari</td><td>kimia (makanan) → kinetik + panas</td></tr><tr><td>Kipas angin</td><td>listrik → kinetik</td></tr></table></div><p>Sumber energi terbarukan: matahari, angin, air, panas bumi, biomassa. Tidak terbarukan: minyak bumi, batu bara, gas alam.</p>`},
{j:'Energi kinetik, potensial & mekanik', h:`<div class="f">Ek = ½ × m × v² &nbsp;|&nbsp; Ep = m × g × h &nbsp;|&nbsp; Em = Ep + Ek</div><p>Energi kinetik bergantung kuadrat kecepatan: jika kecepatan dua kali lipat, Ek menjadi empat kali lipat — itulah sebabnya tabrakan pada kecepatan tinggi sangat berbahaya.</p><p><b>Hukum kekekalan energi mekanik</b>: tanpa gesekan, Em selalu tetap. Saat kelapa jatuh, Ep berkurang dan Ek bertambah dengan jumlah yang sama. Pada ayunan, energi terus berganti bentuk Ep ↔ Ek.</p>`},
{j:'Daya', h:`<p><b>Daya</b> adalah usaha yang dilakukan setiap satuan waktu — seberapa cepat energi dipakai.</p><div class="f">P = W / t &nbsp; (watt, W)</div><p>Dua siswa menaiki tangga yang sama; yang lebih cepat sampai memiliki daya lebih besar walau usahanya sama. 1 tenaga kuda (hp) ≈ 746 W.</p>`},
{j:'Pesawat sederhana: tuas', h:`<p>Pesawat sederhana mempermudah kerja — gaya yang dibutuhkan lebih kecil, tetapi usaha totalnya tetap. Ukurannya adalah <b>keuntungan mekanis</b> (KM = beban / kuasa).</p><div class="f">w × Lb = F × Lk &nbsp;→&nbsp; KM = w/F = Lk/Lb</div><ul><li><b>Jenis 1</b> — titik tumpu di tengah: gunting, linggis, jungkat-jungkit, tang.</li><li><b>Jenis 2</b> — beban di tengah: gerobak satu roda, pembuka tutup botol, pemecah kemiri.</li><li><b>Jenis 3</b> — kuasa di tengah: sekop, pinset, sapu, lengan bawah manusia.</li></ul>`},
{j:'Bidang miring, katrol, roda berporos', h:`<ul><li><b>Bidang miring</b>: KM = s / h (panjang lintasan / tinggi). Contoh: tangga, jalan berkelok di gunung, sekrup, pisau, kapak.</li><li><b>Katrol tetap</b> (sumur timba, tiang bendera): KM = 1 — tidak memperkecil gaya, hanya mengubah arah tarikan agar lebih nyaman.</li><li><b>Katrol bebas</b>: KM = 2. <b>Katrol majemuk (takal)</b>: KM = jumlah tali penopang beban.</li><li><b>Roda berporos</b>: KM = R / r (jari-jari roda / jari-jari poros). Contoh: setir mobil, obeng, gerinda, roda sepeda.</li></ul>`},
],
penemuan:`<h4>🌍 “Beri aku tempat berpijak, akan kuangkat Bumi!”</h4><p>Kalimat itu dikaitkan dengan <b>Archimedes</b> (abad ke-3 SM), yang menjelaskan prinsip tuas secara matematis: tuas seimbang jika hasil kali gaya dengan lengannya sama di kedua sisi. Artinya, dengan lengan kuasa yang cukup panjang, gaya kecil bisa mengangkat beban sangat besar.</p><h4>🔥 James Prescott Joule (1840-an)</h4><p>Joule memasang beban yang jatuh perlahan untuk memutar kincir di dalam bejana air. Gesekan kincir membuat air sedikit menghangat. Ia mengukur bahwa usaha mekanik tertentu <b>selalu</b> menghasilkan jumlah panas yang sama — bukti bahwa energi berubah bentuk, bukan hilang. Satuan energi kini dinamai joule untuk menghormatinya.</p><h4>🧮 Menurunkan Ek = ½mv² dan Ep = mgh</h4><div class="tl"><div>Benda diam (m) didorong gaya F sejauh s. Usaha W = F·s = m·a·s.</div><div>Dari GLBB tanpa waktu: v² = 0 + 2as → a·s = v²/2.</div><div>Maka W = m · v²/2 = <b>½mv²</b>. Usaha itu tersimpan sebagai energi gerak.</div><div>Mengangkat benda setinggi h perlu gaya sebesar beratnya (mg), sehingga W = mg × h = <b>mgh</b>, tersimpan sebagai energi potensial.</div></div><h4>⛰️ Mengapa bidang miring meringankan?</h4><p>Usaha mengangkat lewat bidang miring sama dengan usaha mengangkat lurus: F × s = w × h. Karena s lebih panjang dari h, F lebih kecil: F = w·h/s, sehingga KM = w/F = <b>s/h</b>. Kita “membayar” dengan jarak yang lebih jauh.</p>`,
rumus:[['W = F · s','usaha (J)'],['Ek = ½ · m · v²','energi kinetik'],['Ep = m · g · h','energi potensial'],['Em = Ep + Ek','energi mekanik (tetap tanpa gesekan)'],['P = W / t','daya (watt)'],['w · Lb = F · Lk','tuas'],['KM = w / F','keuntungan mekanis'],['KM = s / h','bidang miring'],['KM = R / r','roda berporos']],
contoh:[
{s:'Ani mendorong lemari dengan gaya 200 N sejauh 3 m. Berapa usahanya?', l:['W = F × s.','W = 200 × 3.'], j:'W = 600 J'},
{s:'Kelapa 2 kg jatuh dari ketinggian 10 m (g = 10 m/s²). Berapa Ep awalnya dan kecepatannya saat menyentuh tanah?', l:['Ep = m·g·h = 2 × 10 × 10 = 200 J.','Di tanah seluruh Ep berubah menjadi Ek: ½ × 2 × v² = 200.','v² = 200 → v = √200 ≈ 14,1 m/s.'], j:'Ep = 200 J; kecepatan saat tiba ≈ 14,1 m/s'},
{s:'Linggis dipakai mengangkat batu 600 N. Lengan beban 20 cm, lengan kuasa 120 cm. Berapa gaya yang diperlukan dan KM-nya?', l:['w × Lb = F × Lk → F = 600 × 20 / 120.','F = 100 N.','KM = Lk / Lb = 120 / 20 = 6.'], j:'F = 100 N dan KM = 6'},
{s:'Peti 1.000 N didorong melalui bidang miring sepanjang 5 m ke truk setinggi 1 m. Berapa gaya minimumnya?', l:['F × s = w × h → F = w × h / s.','F = 1.000 × 1 / 5 = 200 N.','KM = s/h = 5.'], j:'F = 200 N (5 kali lebih ringan)'},
],
kuis:{bahas:'usaha, energi kinetik & potensial, hukum kekekalan energi, daya, dan jenis-jenis pesawat sederhana', soal:[
{q:'Gaya 25 N memindahkan benda sejauh 4 m searah gaya. Usahanya…', o:['100 J','29 J','6,25 J','21 J'], a:0, p:'W = F × s = 25 × 4 = 100 J.'},
{q:'Energi kinetik benda 2 kg yang bergerak 3 m/s adalah…', o:['9 J','6 J','18 J','3 J'], a:0, p:'Ek = ½ × m × v² = ½ × 2 × 3² = ½ × 2 × 9 = 9 J.'},
{q:'Gerobak satu roda termasuk tuas jenis…', o:['pertama','kedua','ketiga','bukan tuas'], a:1, p:'Pada gerobak, titik tumpu di roda (ujung), kuasa di pegangan (ujung lain), dan beban di tengah. Beban di tengah = tuas jenis kedua.'},
{q:'Keuntungan mekanis katrol tetap adalah…', o:['1','2','0','4'], a:0, p:'Katrol tetap hanya mengubah arah gaya; gaya tarik sama dengan berat beban sehingga KM = 1.'},
{q:'Bidang miring panjangnya 6 m dan tingginya 2 m. Keuntungan mekanisnya…', o:['3','12','4','8'], a:0, p:'KM = s / h = 6 / 2 = 3.'},
]}});

C({id:'f6', mapel:'fisika', no:6, ikon:'🔊', judul:'Getaran, Gelombang & Bunyi', lab:'gelombang',
ringkas:'Getaran adalah gerak bolak-balik, gelombang adalah getaran yang merambat membawa energi, dan bunyi adalah gelombang longitudinal yang memerlukan medium.',
svg:`<svg class="ill" viewBox="0 0 320 168"><line x1="10" y1="84" x2="310" y2="84" stroke="#cbd5e1" stroke-dasharray="4"/><path d="${(()=>{let d='';for(let x=10;x<=310;x+=3)d+=(x>10?'L':'M')+x+' '+(84-40*Math.sin((x-10)/150*2*Math.PI)).toFixed(1);return d})()}" fill="none" stroke="#2f7de1" stroke-width="4"/><text x="47" y="34" text-anchor="middle" font-size="12" fill="#16323f" font-weight="700">bukit</text><text x="122" y="146" text-anchor="middle" font-size="12" fill="#16323f" font-weight="700">lembah</text><line x1="10" y1="158" x2="160" y2="158" stroke="#f59e0b" stroke-width="3"/><text x="85" y="152" text-anchor="middle" font-size="12" fill="#b45309">1 λ</text><line x1="47" y1="84" x2="47" y2="44" stroke="#ef4444" stroke-width="2"/><text x="52" y="66" font-size="11" fill="#ef4444">A</text><text x="230" y="24" font-size="13" font-weight="700" fill="#16323f">v = λ · f</text></svg>`,
sesi:[
{j:'Getaran', h:`<p><b>Getaran</b> adalah gerak bolak-balik melalui titik setimbang. Pada bandul A–B–C, satu getaran penuh adalah A → B → C → B → A.</p><ul><li><b>Amplitudo</b>: simpangan terjauh dari titik setimbang.</li><li><b>Frekuensi (f)</b>: banyak getaran tiap detik, satuan hertz (Hz).</li><li><b>Periode (T)</b>: waktu untuk satu getaran.</li></ul><div class="f">f = n / t &nbsp;|&nbsp; T = t / n &nbsp;|&nbsp; f = 1 / T</div>`},
{j:'Gelombang dan jenisnya', h:`<p><b>Gelombang</b> adalah getaran yang merambat. Yang dipindahkan adalah <b>energi</b>, bukan mediumnya — bola di kolam hanya naik turun, tidak ikut terbawa ombak kecil.</p><ul><li><b>Transversal</b>: arah getar tegak lurus arah rambat, terdiri dari bukit & lembah. Contoh: gelombang tali, permukaan air, cahaya.</li><li><b>Longitudinal</b>: arah getar sejajar arah rambat, terdiri dari rapatan & renggangan. Contoh: slinki yang didorong-tarik, bunyi.</li></ul><p>Berdasarkan medium: <b>gelombang mekanik</b> perlu medium (bunyi, tali), <b>gelombang elektromagnetik</b> tidak perlu (cahaya, sinyal radio, sinar-X).</p>`},
{j:'Panjang gelombang & cepat rambat', h:`<p><b>Panjang gelombang (λ)</b> adalah jarak satu gelombang: 1 bukit + 1 lembah (transversal) atau 1 rapatan + 1 renggangan (longitudinal).</p><div class="f">v = λ × f = λ / T</div><p>Contoh: gelombang air dengan λ = 2 m dan f = 0,5 Hz merambat dengan v = 1 m/s.</p>`},
{j:'Bunyi', h:`<p>Bunyi adalah gelombang longitudinal yang <b>memerlukan medium</b>. Di ruang hampa (seperti di Bulan) bunyi tidak merambat, sehingga astronaut berbicara lewat radio.</p><p>Cepat rambat bunyi: zat padat &gt; cair &gt; gas. Di udara ±340 m/s, di air ±1.500 m/s, di besi ±5.000 m/s.</p><div class="tbl"><table><tr><th>Jenis</th><th>Frekuensi</th><th>Contoh pendengar</th></tr><tr><td>Infrasonik</td><td>&lt; 20 Hz</td><td>gajah, paus</td></tr><tr><td>Audiosonik</td><td>20–20.000 Hz</td><td>manusia</td></tr><tr><td>Ultrasonik</td><td>&gt; 20.000 Hz</td><td>kelelawar, lumba-lumba, anjing</td></tr></table></div><p><b>Tinggi rendah nada</b> ditentukan frekuensi; <b>kuat lemah bunyi</b> ditentukan amplitudo; <b>warna bunyi (timbre)</b> membedakan suara gitar dan piano walau nadanya sama.</p>`},
{j:'Pemantulan bunyi & resonansi', h:`<ul><li><b>Gaung (kerdam)</b>: pantulan datang hampir bersamaan dengan bunyi asli sehingga suara tidak jelas. Dicegah dengan peredam (karpet, busa, gorden) di bioskop dan studio.</li><li><b>Gema</b>: pantulan terdengar setelah bunyi asli selesai, misalnya berteriak di tebing.</li></ul><p>Pemantulan dipakai untuk mengukur jarak (SONAR, USG, ekolokasi kelelawar):</p><div class="f">s = v × t / 2 &nbsp; (dibagi 2 karena bunyi pergi-pulang)</div><p><b>Resonansi</b> adalah ikut bergetarnya benda karena frekuensinya sama dengan sumber getar. Contoh: kolom udara gitar dan kentongan memperkuat bunyi; garpu tala yang sama ikut berbunyi; kaca bergetar saat truk lewat.</p>`},
],
penemuan:`<h4>🧮 Asal rumus v = λ · f</h4><p>Dalam waktu satu periode (T), satu gelombang penuh terbentuk dan merambat sejauh satu panjang gelombang (λ). Kecepatan = jarak / waktu = <b>λ / T</b>. Karena T = 1/f, maka v = <b>λ × f</b>.</p><h4>🔔 Robert Boyle dan jam di dalam tabung (1660)</h4><p>Boyle menaruh jam berdering di dalam tabung kaca lalu memompa udaranya keluar. Makin sedikit udara, makin pelan bunyinya — hingga nyaris tak terdengar. Kesimpulan: <b>bunyi memerlukan medium</b>.</p><h4>💥 Mengukur kecepatan bunyi</h4><p>Pada abad ke-17, ilmuwan menembakkan meriam dari jarak yang diketahui dan mengukur selang waktu antara melihat kilatan dan mendengar dentumannya. Cahaya tiba hampir seketika, sehingga v bunyi = jarak / selang waktu. Cara yang sama bisa kamu pakai untuk memperkirakan jarak petir!</p><h4>🦇 Kelelawar “melihat” dengan telinga</h4><p>Pada 1790-an, Lazzaro Spallanzani menemukan bahwa kelelawar yang ditutup matanya tetap bisa terbang menghindari tali, tetapi bingung jika telinganya ditutup. Baru pada 1930-an Donald Griffin membuktikan kelelawar memancarkan ultrasonik dan mendengar pantulannya — ekolokasi, prinsip yang sama dengan SONAR.</p><h4>🎸 Pythagoras dan senar</h4><p>Pythagoras (abad ke-6 SM) mengamati bahwa senar yang dipendekkan setengahnya menghasilkan nada satu oktaf lebih tinggi. Kini kita tahu frekuensinya menjadi dua kali lipat.</p>`,
rumus:[['f = n / t','frekuensi (Hz)'],['T = t / n = 1 / f','periode (s)'],['v = λ · f = λ / T','cepat rambat gelombang'],['s = v · t / 2','jarak dengan pantulan bunyi']],
contoh:[
{s:'Sebuah bandul melakukan 60 getaran dalam 15 sekon. Tentukan frekuensi dan periodenya.', l:['f = n / t = 60 / 15 = 4 Hz.','T = 1 / f = 1/4 = 0,25 s.'], j:'f = 4 Hz dan T = 0,25 s'},
{s:'Gelombang memiliki panjang gelombang 2 m dan frekuensi 5 Hz. Berapa cepat rambatnya?', l:['v = λ × f.','v = 2 × 5.'], j:'v = 10 m/s'},
{s:'Kapal memancarkan sonar ke dasar laut; pantulannya diterima setelah 4 s. Jika v bunyi di air 1.500 m/s, berapa kedalaman laut?', l:['Bunyi menempuh jalan pergi-pulang, jadi dibagi 2.','s = v × t / 2 = 1.500 × 4 / 2.'], j:'Kedalaman laut = 3.000 m'},
{s:'Kilat terlihat, lalu guntur terdengar 3 s kemudian. Berapa jarak petir? (v bunyi = 340 m/s)', l:['Cahaya tiba hampir seketika, jadi 3 s adalah waktu tempuh bunyi.','s = v × t = 340 × 3.'], j:'Petir berjarak ±1.020 m'},
],
kuis:{bahas:'frekuensi dan periode, gelombang transversal & longitudinal, rumus v = λ·f, sifat bunyi, pemantulan bunyi, dan resonansi', soal:[
{q:'Sebuah benda bergetar 120 kali dalam 30 sekon. Frekuensinya…', o:['4 Hz','0,25 Hz','3.600 Hz','90 Hz'], a:0, p:'f = n / t = 120 / 30 = 4 Hz.'},
{q:'Contoh gelombang longitudinal adalah…', o:['cahaya','gelombang pada tali','bunyi','gelombang permukaan air'], a:2, p:'Bunyi merambat dalam bentuk rapatan dan renggangan yang arah getarnya sejajar arah rambat, jadi longitudinal.'},
{q:'Gelombang dengan λ = 0,5 m dan f = 680 Hz memiliki cepat rambat…', o:['340 m/s','1.360 m/s','680,5 m/s','0,00074 m/s'], a:0, p:'v = λ × f = 0,5 × 680 = 340 m/s.'},
{q:'Gelombang ultrasonik dimanfaatkan untuk…', o:['USG dan sonar','radio FM','kacamata','termometer'], a:0, p:'Ultrasonik (> 20.000 Hz) dipantulkan oleh organ tubuh atau dasar laut, sehingga dipakai pada USG dan SONAR.'},
{q:'Astronaut di Bulan tidak dapat saling mendengar secara langsung karena…', o:['suhu terlalu dingin','tidak ada udara sebagai medium','gravitasi kecil','Bulan gelap'], a:1, p:'Bunyi adalah gelombang mekanik yang butuh medium. Bulan hampir tidak memiliki atmosfer, sehingga bunyi tidak bisa merambat.'},
]}});

C({id:'f7', mapel:'fisika', no:7, ikon:'🔍', judul:'Cahaya & Alat Optik', lab:'lensa',
ringkas:'Cahaya merambat lurus, dapat dipantulkan dan dibiaskan. Prinsip ini menjelaskan cermin, lensa, mata kita, kacamata, hingga mikroskop.',
svg:`<svg class="ill" viewBox="0 0 320 168"><line x1="10" y1="96" x2="310" y2="96" stroke="#94a3b8"/><ellipse cx="170" cy="96" rx="10" ry="66" fill="#bae6fd" stroke="#0b7d84" stroke-width="2"/><line x1="60" y1="96" x2="60" y2="56" stroke="#f97316" stroke-width="4"/><polygon points="54,64 66,64 60,54" fill="#f97316"/><line x1="60" y1="56" x2="170" y2="56" stroke="#facc15" stroke-width="2"/><line x1="170" y1="56" x2="290" y2="140" stroke="#facc15" stroke-width="2"/><line x1="60" y1="56" x2="290" y2="140" stroke="#fde047" stroke-width="2" opacity=".8"/><line x1="268" y1="96" x2="268" y2="128" stroke="#2f7de1" stroke-width="4"/><polygon points="262,120 274,120 268,130" fill="#2f7de1"/><circle cx="230" cy="96" r="4" fill="#ef4444"/><text x="230" y="112" text-anchor="middle" font-size="11" fill="#ef4444">F</text><circle cx="110" cy="96" r="4" fill="#ef4444"/><text x="110" y="112" text-anchor="middle" font-size="11" fill="#ef4444">F</text><text x="60" y="118" text-anchor="middle" font-size="11">benda</text><text x="312" y="160" text-anchor="end" font-size="11" fill="#2f7de1">bayangan nyata, terbalik</text><text x="12" y="160" font-size="13" font-weight="700" fill="#16323f">1/f = 1/s + 1/s'</text></svg>`,
sesi:[
{j:'Sifat-sifat cahaya', h:`<ul><li><b>Merambat lurus</b> → terbentuk bayangan gelap di belakang benda tak tembus cahaya.</li><li><b>Dapat dipantulkan</b> (cermin) dan <b>dibiaskan</b> (lensa, air).</li><li><b>Gelombang elektromagnetik</b> → bisa merambat di ruang hampa dengan kecepatan ±300.000 km/s (3 × 10⁸ m/s).</li><li><b>Dapat diuraikan (dispersi)</b> → cahaya putih terurai menjadi merah, jingga, kuning, hijau, biru, nila, ungu (“mejikuhibiniu”) oleh prisma atau butiran air hujan (pelangi).</li></ul><p>Benda yang dapat memancarkan cahaya sendiri disebut sumber cahaya (Matahari, lampu); benda lain seperti Bulan hanya memantulkan.</p>`},
{j:'Pemantulan & cermin datar', h:`<p><b>Hukum pemantulan</b>: (1) sinar datang, sinar pantul, dan garis normal terletak pada satu bidang datar; (2) <b>sudut datang = sudut pantul</b>.</p><p>Pemantulan teratur terjadi di permukaan rata (cermin), pemantulan baur terjadi di permukaan kasar (dinding) sehingga kita bisa melihat benda dari berbagai arah.</p><p><b>Cermin datar</b>: bayangan maya, tegak, sama besar, jarak bayangan = jarak benda, dan kiri-kanan tertukar (tulisan “AMBULANS” dibalik agar terbaca di spion).</p><div class="f">Jumlah bayangan dua cermin bersudut α: n = 360°/α − 1</div>`},
{j:'Cermin cekung & cembung', h:`<ul><li><b>Cermin cekung (konkaf)</b>: mengumpulkan cahaya (konvergen), f bernilai positif. Bayangannya bisa nyata atau maya tergantung letak benda. Dipakai pada lampu senter, lampu mobil, cermin rias, dan antena parabola.</li><li><b>Cermin cembung (konveks)</b>: menyebarkan cahaya (divergen), f negatif. Bayangan <b>selalu maya, tegak, diperkecil</b> sehingga bidang pandangnya luas. Dipakai pada spion kendaraan dan cermin di tikungan jalan.</li></ul><div class="f">1/f = 1/s + 1/s' &nbsp;|&nbsp; f = R/2 &nbsp;|&nbsp; M = |s'/s| = |h'/h|</div><p>s' positif → bayangan nyata (di depan cermin); s' negatif → bayangan maya (di belakang cermin).</p>`},
{j:'Pembiasan & lensa', h:`<p><b>Pembiasan</b> adalah pembelokan cahaya saat melewati dua medium yang kerapatannya berbeda. Dari medium kurang rapat ke lebih rapat (udara → air), cahaya dibelokkan mendekati garis normal. Akibatnya pensil tampak patah di dalam air dan dasar kolam tampak lebih dangkal.</p><ul><li><b>Lensa cembung (positif, konvergen)</b>: lup, kamera, proyektor, lensa mata.</li><li><b>Lensa cekung (negatif, divergen)</b>: kacamata rabun jauh, lubang intip pintu.</li></ul><div class="f">Kekuatan lensa: P = 1/f (f dalam meter) = 100/f (f dalam cm) &nbsp;→&nbsp; dioptri (D)</div>`},
{j:'Mata dan cacat mata', h:`<p>Bagian mata: kornea (pelindung), iris (pemberi warna & pengatur pupil), pupil (lubang masuk cahaya), <b>lensa mata</b> (memfokuskan; dapat menebal-menipis = <b>daya akomodasi</b>), retina (tempat bayangan: nyata, terbalik, diperkecil), dan saraf optik (meneruskan ke otak).</p><p>Mata normal: titik dekat 25 cm, titik jauh tak terhingga.</p><div class="tbl"><table><tr><th>Cacat mata</th><th>Penyebab</th><th>Kacamata</th></tr><tr><td>Miopi (rabun jauh)</td><td>bayangan jatuh di depan retina</td><td>lensa cekung, P = −100/PR</td></tr><tr><td>Hipermetropi (rabun dekat)</td><td>bayangan jatuh di belakang retina</td><td>lensa cembung, P = 4 − 100/PP</td></tr><tr><td>Presbiopi (mata tua)</td><td>daya akomodasi berkurang</td><td>lensa rangkap (bifokal)</td></tr><tr><td>Astigmatisma</td><td>kelengkungan kornea tidak rata</td><td>lensa silinder</td></tr></table></div>`},
{j:'Alat optik lainnya', h:`<ul><li><b>Lup (kaca pembesar)</b>: lensa cembung; benda diletakkan di antara lensa dan titik fokus sehingga bayangan maya, tegak, diperbesar. Perbesaran untuk mata tak berakomodasi M = 25/f.</li><li><b>Kamera</b>: lensa cembung membentuk bayangan nyata, terbalik, diperkecil pada sensor/film; diafragma mengatur banyak cahaya seperti pupil.</li><li><b>Mikroskop</b>: dua lensa cembung (objektif dekat benda & okuler dekat mata) untuk melihat benda sangat kecil seperti sel.</li><li><b>Teropong/teleskop</b>: untuk melihat benda jauh seperti bintang dan planet.</li><li><b>Periskop</b>: dua cermin datar atau prisma, dipakai di kapal selam.</li></ul>`},
],
penemuan:`<h4>👁️ Ibnu al-Haytham — Bapak Optika (±1021)</h4><p>Dulu banyak orang percaya mata memancarkan sinar ke benda. Ilmuwan Arab <b>Ibnu al-Haytham</b> membantahnya lewat percobaan: cahaya datang dari benda (atau dipantulkan benda) lalu masuk ke mata. Ia mempelajari <b>kamera obscura</b> (ruang gelap berlubang kecil) yang membentuk bayangan terbalik, dan membuktikan cahaya merambat lurus. Bukunya <i>Kitab al-Manazir</i> sangat berpengaruh bagi ilmuwan Eropa.</p><div class="tl"><div><b>1621</b> — Willebrord Snell merumuskan hukum pembiasan.</div><div><b>1666</b> — Isaac Newton memakai prisma untuk menunjukkan cahaya putih adalah campuran berbagai warna.</div><div><b>1670-an</b> — Antonie van Leeuwenhoek membuat lensa kecil berkualitas tinggi dan melihat bakteri pertama kali.</div></div>
<h4>🧮 Menurunkan rumus cermin 1/f = 1/s + 1/s'</h4><p>Gunakan dua sinar istimewa pada cermin cekung dan dua pasang segitiga sebangun:</p><div class="tl"><div>Sinar melalui titik pusat cermin menghasilkan segitiga sebangun → <b>h'/h = s'/s</b>.</div><div>Sinar sejajar sumbu dipantulkan melalui fokus → segitiga sebangun di sekitar F → <b>h'/h = (s' − f)/f</b>.</div><div>Samakan: s'/s = (s' − f)/f → s'·f = s·s' − s·f → s'·f + s·f = s·s'.</div><div>Bagi kedua ruas dengan s·s'·f: <b>1/s + 1/s' = 1/f</b>. Rumus yang sama berlaku untuk lensa tipis.</div></div>`,
rumus:[['sudut datang = sudut pantul','hukum pemantulan'],['n = 360°/α − 1','jumlah bayangan dua cermin bersudut'],["1/f = 1/s + 1/s'",'cermin & lensa'],['f = R / 2','fokus = setengah jari-jari kelengkungan'],["M = |s'/s| = |h'/h|",'perbesaran bayangan'],['P = 100 / f (cm)','kekuatan lensa (dioptri)'],['P = −100 / PR','kacamata miopi'],['P = 4 − 100 / PP','kacamata hipermetropi'],['M = 25 / f','lup, mata tak berakomodasi']],
contoh:[
{s:'Benda diletakkan 30 cm di depan cermin cekung berfokus 10 cm. Tentukan letak, perbesaran, dan sifat bayangan.', l:["1/s' = 1/f − 1/s = 1/10 − 1/30 = 3/30 − 1/30 = 2/30.","s' = 15 cm (positif → nyata, di depan cermin).","M = s'/s = 15/30 = 0,5 → diperkecil."], j:"s' = 15 cm, M = 0,5×; bayangan nyata, terbalik, diperkecil"},
{s:'Benda berada 6 cm di depan lensa cembung berfokus 12 cm. Bagaimana bayangannya?', l:["1/s' = 1/12 − 1/6 = 1/12 − 2/12 = −1/12.","s' = −12 cm (negatif → maya, di depan lensa).","M = |s'/s| = 12/6 = 2 → diperbesar 2 kali."], j:'Bayangan maya, tegak, diperbesar 2× — prinsip lup'},
{s:'Seorang penderita miopi memiliki titik jauh 200 cm. Berapa kekuatan lensa kacamatanya?', l:['P = −100 / PR.','P = −100 / 200.'], j:'P = −0,5 dioptri (lensa cekung)'},
{s:'Titik dekat mata seorang kakek 50 cm. Berapa kekuatan kacamata bacanya?', l:['P = 4 − 100/PP.','P = 4 − 100/50 = 4 − 2.'], j:'P = +2 dioptri (lensa cembung)'},
],
kuis:{bahas:'sifat cahaya, hukum pemantulan, cermin cekung & cembung, rumus cermin/lensa, kekuatan lensa, cacat mata, dan alat optik', soal:[
{q:'Spion kendaraan menggunakan cermin…', o:['datar','cekung','cembung','silinder'], a:2, p:'Cermin cembung selalu menghasilkan bayangan maya, tegak, dan diperkecil sehingga bidang pandangnya luas — cocok untuk melihat kendaraan di belakang.'},
{q:'Benda 20 cm di depan cermin cekung yang fokusnya 10 cm. Jarak bayangannya…', o:['20 cm','10 cm','6,7 cm','−20 cm'], a:0, p:"1/s' = 1/10 − 1/20 = 2/20 − 1/20 = 1/20, jadi s' = 20 cm (benda tepat di titik pusat kelengkungan, bayangan sama besar)."},
{q:'Lensa dengan jarak fokus 50 cm memiliki kekuatan…', o:['2 D','0,5 D','50 D','0,02 D'], a:0, p:'P = 100/f = 100/50 = 2 dioptri.'},
{q:'Penderita rabun jauh (miopi) dibantu dengan kacamata berlensa…', o:['cembung','cekung','bifokal','silinder'], a:1, p:'Pada miopi bayangan jatuh di depan retina. Lensa cekung menyebarkan cahaya sehingga bayangan mundur tepat ke retina.'},
{q:'Pelangi terbentuk karena…', o:['pemantulan baur','pembiasan dan penguraian cahaya oleh butiran air','gema','radiasi panas'], a:1, p:'Butiran air hujan berperan seperti prisma: cahaya matahari dibiaskan dan diuraikan (dispersi) menjadi berbagai warna.'},
]}});

C({id:'f8', mapel:'fisika', no:8, ikon:'⚡', judul:'Listrik & Magnet', lab:'listrik',
ringkas:'Dari muatan listrik statis hingga arus di rumah kita, dan dari magnet sederhana hingga generator dan trafo — listrik dan magnet ternyata saling berhubungan.',
svg:`<svg class="ill" viewBox="0 0 320 168"><path d="M40 40H280V130H40Z" fill="none" stroke="#475569" stroke-width="3"/><rect x="28" y="72" width="24" height="26" fill="#fff"/><line x1="22" y1="78" x2="58" y2="78" stroke="#16323f" stroke-width="4"/><line x1="30" y1="92" x2="50" y2="92" stroke="#16323f" stroke-width="4"/><text x="8" y="92" font-size="12" font-weight="700">V</text><rect x="120" y="32" width="50" height="16" fill="#fff" stroke="#e58a00" stroke-width="3"/><text x="145" y="26" text-anchor="middle" font-size="12" font-weight="700" fill="#b45309">R</text><circle cx="230" cy="40" r="26" fill="#fde047" opacity=".5"/><circle cx="230" cy="40" r="14" fill="#fef9c3" stroke="#475569" stroke-width="2"/><path d="M222 40l5 6 6-10 5 4" fill="none" stroke="#b45309" stroke-width="1.5"/><circle cx="160" cy="130" r="12" fill="#fff" stroke="#2f7de1" stroke-width="3"/><text x="160" y="135" text-anchor="middle" font-size="12" font-weight="700" fill="#2f7de1">A</text><path d="M90 130h0" /><text x="200" y="110" font-size="13" font-weight="700" fill="#16323f">V = I · R</text><line x1="90" y1="122" x2="120" y2="122" stroke="#16a34a" stroke-width="2" marker-end="url(#a4)"/><text x="90" y="116" font-size="11" fill="#16a34a">I</text><defs><marker id="a4" markerWidth="8" markerHeight="8" refX="4" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="#16a34a"/></marker></defs></svg>`,
sesi:[
{j:'Listrik statis', h:`<p>Atom memiliki proton (+) di inti dan elektron (−) di kulit. Benda menjadi bermuatan karena <b>perpindahan elektron</b> (proton tidak berpindah).</p><ul><li>Benda kelebihan elektron → bermuatan <b>negatif</b>.</li><li>Benda kekurangan elektron → bermuatan <b>positif</b>.</li></ul><p>Contoh: penggaris plastik digosok kain wol → elektron pindah ke plastik → plastik negatif dan bisa menarik sobekan kertas. Batang kaca digosok kain sutra → elektron pindah ke sutra → kaca positif.</p><p>Muatan sejenis tolak-menolak, berlawanan jenis tarik-menarik. <b>Elektroskop</b> dipakai untuk mendeteksi muatan. Petir adalah lompatan muatan antara awan dan bumi; penangkal petir menyalurkannya aman ke tanah.</p><div class="f">Hukum Coulomb: F = k × q₁ × q₂ / r² &nbsp;(k = 9 × 10⁹ N·m²/C²)</div>`},
{j:'Arus listrik & Hukum Ohm', h:`<p><b>Arus listrik</b> adalah aliran muatan dalam rangkaian tertutup. Arus konvensional mengalir dari kutub + ke −, sedangkan elektron mengalir sebaliknya.</p><div class="f">I = Q / t &nbsp;|&nbsp; V = I × R</div><p>V = tegangan/beda potensial (volt), I = kuat arus (ampere), R = hambatan (ohm, Ω). Amperemeter dipasang <b>seri</b>, voltmeter dipasang <b>paralel</b>.</p><p>Hambatan kawat bergantung panjang (L), luas penampang (A), dan jenis bahan (ρ): <b>R = ρL/A</b>. Kawat panjang dan tipis berhambatan besar.</p><p>Bahan konduktor: tembaga, aluminium, besi. Isolator: plastik, karet, kaca. Semikonduktor: silikon (bahan chip).</p>`},
{j:'Rangkaian seri & paralel', h:`<div class="tbl"><table><tr><th></th><th>Seri</th><th>Paralel</th></tr><tr><td>Susunan</td><td>berderet, satu jalur</td><td>bercabang</td></tr><tr><td>Hambatan total</td><td>Rₜ = R₁ + R₂ + …</td><td>1/Rₜ = 1/R₁ + 1/R₂ + …</td></tr><tr><td>Arus</td><td>sama di semua hambatan</td><td>terbagi ke tiap cabang</td></tr><tr><td>Tegangan</td><td>terbagi</td><td>sama di semua cabang</td></tr><tr><td>Jika satu lampu putus</td><td>semua padam</td><td>lainnya tetap menyala</td></tr></table></div><p>Instalasi listrik rumah memakai rangkaian <b>paralel</b> agar tiap alat mendapat 220 V dan bisa dinyalakan sendiri-sendiri.</p><div class="f">Hukum I Kirchhoff: ΣI masuk = ΣI keluar</div>`},
{j:'Energi & daya listrik', h:`<div class="f">W = V × I × t = I² × R × t = V² × t / R &nbsp;|&nbsp; P = V × I</div><p>Tagihan listrik dihitung dalam <b>kWh</b> (kilowatt-jam): energi alat 1.000 W yang menyala 1 jam. Rumus: energi (kWh) = daya (kW) × waktu (jam).</p><p>Cara hemat energi: matikan alat yang tidak dipakai, pakai lampu LED, cabut charger setelah penuh, manfaatkan cahaya matahari siang hari.</p>`},
{j:'Kemagnetan', h:`<p>Magnet punya dua kutub: utara (U) dan selatan (S). Kutub sejenis tolak-menolak, berbeda jenis tarik-menarik. Garis gaya magnet keluar dari kutub U menuju kutub S.</p><ul><li><b>Feromagnetik</b> (ditarik kuat): besi, baja, nikel, kobalt.</li><li><b>Paramagnetik</b> (ditarik lemah): aluminium, platina.</li><li><b>Diamagnetik</b> (sedikit ditolak): emas, perak, tembaga, air.</li></ul><p>Cara membuat magnet: <b>menggosok</b> searah, <b>induksi</b> (didekatkan ke magnet), dan <b>elektromagnet</b> (kumparan dialiri arus). Elektromagnet makin kuat jika lilitan ditambah, arus diperbesar, atau diberi inti besi lunak. Dipakai di bel listrik, relai, crane pengangkat besi, dan kereta maglev.</p><p><b>Bumi adalah magnet raksasa.</b> Kutub utara jarum kompas menunjuk ke utara geografis, yang sebenarnya adalah kutub selatan magnet Bumi.</p>`},
{j:'Induksi elektromagnetik & transformator', h:`<p>Jika magnet digerakkan keluar-masuk kumparan, jarum galvanometer menyimpang: timbul <b>arus induksi</b> (GGL induksi) karena jumlah garis gaya magnet yang dilingkupi kumparan berubah. GGL makin besar jika magnet digerakkan lebih cepat, lilitan lebih banyak, atau magnet lebih kuat.</p><p>Penerapannya: <b>generator</b> & dinamo sepeda (gerak → listrik), mikrofon, kompor induksi.</p><p><b>Transformator (trafo)</b> mengubah tegangan bolak-balik (AC):</p><div class="f">Vp / Vs = Np / Ns = Is / Ip &nbsp;|&nbsp; η = Ps / Pp × 100%</div><p><b>Step-up</b> (Ns &gt; Np) menaikkan tegangan — dipakai di pembangkit agar listrik dikirim jarak jauh dengan sedikit energi terbuang. <b>Step-down</b> (Ns &lt; Np) menurunkan tegangan — dipakai di adaptor charger HP.</p>`},
],
penemuan:`<div class="tl"><div><b>1785 — Charles-Augustin de Coulomb</b> memakai <b>neraca puntir</b>: dua bola bermuatan saling tolak dan memuntir kawat halus. Dari besar puntiran, ia menemukan gaya sebanding dengan hasil kali muatan dan berbanding terbalik dengan kuadrat jarak — jarak 2× lebih jauh, gaya menjadi ¼.</div><div><b>1800 — Alessandro Volta</b> menumpuk keping seng–tembaga berselang kain basah garam → baterai pertama (tumpukan volta). Satuan volt untuk menghormatinya.</div><div><b>1820 — Hans Christian Ørsted</b> secara tak sengaja melihat jarum kompas menyimpang di dekat kawat berarus saat kuliah. Bukti pertama bahwa <b>listrik menghasilkan magnet</b>.</div><div><b>1827 — Georg Simon Ohm</b> menguji kawat dengan berbagai panjang dan menemukan bahwa perbandingan tegangan dengan arus selalu tetap untuk satu kawat. Nilai tetap itu disebut hambatan: <b>R = V/I</b>.</div><div><b>1831 — Michael Faraday</b> membalik pertanyaan Ørsted: “Bisakah magnet menghasilkan listrik?” Ia menggerakkan magnet dalam kumparan dan arus pun mengalir — <b>induksi elektromagnetik</b>, dasar semua generator dan trafo di dunia.</div><div><b>1845 — Gustav Kirchhoff</b> merumuskan hukum percabangan arus.</div></div>
<h4>🧮 Menurunkan rumus daya listrik</h4><p>Tegangan V adalah energi per muatan (joule per coulomb). Jika muatan Q melewati beda potensial V, energinya <b>W = Q·V</b>. Karena Q = I·t, maka <b>W = V·I·t</b>. Daya adalah energi per waktu: P = W/t = <b>V·I</b>. Substitusi V = I·R memberi <b>P = I²R</b>.</p><h4>🧮 Rumus trafo</h4><p>Setiap lilitan di kumparan primer dan sekunder mengalami perubahan magnet yang sama, sehingga tegangan per lilitan sama: Vp/Np = Vs/Ns. Pada trafo ideal tidak ada energi hilang, jadi Vp·Ip = Vs·Is.</p>`,
rumus:[['F = k · q₁ · q₂ / r²','Hukum Coulomb'],['I = Q / t','kuat arus'],['V = I · R','Hukum Ohm'],['R = ρ · L / A','hambatan kawat'],['Rₜ = R₁ + R₂','rangkaian seri'],['1/Rₜ = 1/R₁ + 1/R₂','rangkaian paralel'],['W = V · I · t','energi listrik'],['P = V · I = I² · R','daya listrik'],['Vp/Vs = Np/Ns = Is/Ip','transformator'],['η = Ps/Pp × 100%','efisiensi trafo']],
contoh:[
{s:'Lampu dipasang pada tegangan 220 V dan dialiri arus 0,5 A. Berapa hambatan dan dayanya?', l:['R = V / I = 220 / 0,5 = 440 Ω.','P = V × I = 220 × 0,5 = 110 W.'], j:'R = 440 Ω dan P = 110 W'},
{s:'Hambatan 2 Ω dan 4 Ω dirangkai seri dengan baterai 12 V. Tentukan arus dan tegangan tiap hambatan.', l:['Rₜ = 2 + 4 = 6 Ω.','I = V / Rₜ = 12 / 6 = 2 A (sama di kedua hambatan).','V₁ = 2 × 2 = 4 V; V₂ = 2 × 4 = 8 V (jumlahnya 12 V).'], j:'I = 2 A; V₁ = 4 V; V₂ = 8 V'},
{s:'Hambatan 6 Ω dan 3 Ω dirangkai paralel. Berapa hambatan totalnya?', l:['1/Rₜ = 1/6 + 1/3 = 1/6 + 2/6 = 3/6.','Rₜ = 6/3 = 2 Ω.'], j:'Rₜ = 2 Ω (lebih kecil dari hambatan terkecil)'},
{s:'TV 100 W menyala 5 jam sehari selama 30 hari. Jika tarif Rp1.500/kWh, berapa biayanya?', l:['Energi = 0,1 kW × 5 jam × 30 = 15 kWh.','Biaya = 15 × Rp1.500.'], j:'Biaya = Rp22.500 per bulan'},
{s:'Trafo memiliki 1.000 lilitan primer dan 100 lilitan sekunder. Jika Vp = 220 V, berapa Vs?', l:['Vs = Vp × Ns / Np.','Vs = 220 × 100 / 1.000 = 22 V.'], j:'Vs = 22 V (trafo step-down)'},
],
kuis:{bahas:'listrik statis, Hukum Ohm, rangkaian seri dan paralel, energi & daya listrik, kemagnetan, induksi elektromagnetik, dan transformator', soal:[
{q:'Tegangan 12 V diberikan pada hambatan 4 Ω. Kuat arusnya…', o:['3 A','48 A','0,33 A','16 A'], a:0, p:'I = V / R = 12 / 4 = 3 A.'},
{q:'Hambatan 3 Ω dan 6 Ω dirangkai paralel. Hambatan totalnya…', o:['2 Ω','9 Ω','18 Ω','4,5 Ω'], a:0, p:'1/Rₜ = 1/3 + 1/6 = 2/6 + 1/6 = 3/6 → Rₜ = 2 Ω.'},
{q:'Instalasi listrik di rumah umumnya dirangkai…', o:['seri','paralel','seri semua lampu','tidak dirangkai'], a:1, p:'Rangkaian paralel memberi tegangan penuh 220 V ke setiap alat, dan jika satu alat mati yang lain tetap menyala.'},
{q:'Lampu 40 W menyala selama 10 jam. Energi yang dipakai…', o:['0,4 kWh','4 kWh','400 kWh','0,04 kWh'], a:0, p:'Energi = 0,04 kW × 10 jam = 0,4 kWh (= 400 Wh).'},
{q:'Trafo dengan Np = 200 dan Ns = 1.000 diberi Vp = 10 V. Vs-nya…', o:['50 V','2 V','10 V','2.000 V'], a:0, p:'Vs = Vp × Ns/Np = 10 × 1.000/200 = 50 V. Karena Ns > Np, ini trafo step-up.'},
]}});

C({id:'f9', mapel:'fisika', no:9, ikon:'🪐', judul:'Tata Surya', lab:'tatasurya',
ringkas:'Tata surya terdiri dari Matahari, delapan planet, satelit, asteroid, komet, dan meteoroid. Gerak rotasi dan revolusi Bumi serta Bulan mengatur siang-malam, musim, fase bulan, dan gerhana.',
svg:`<svg class="ill" viewBox="0 0 320 168"><rect width="320" height="168" fill="#0f172a" rx="0"/>${Array.from({length:30},(_,i)=>`<circle cx="${(i*67)%320}" cy="${(i*41)%168}" r="1" fill="#fff" opacity=".6"/>`).join('')}<circle cx="0" cy="84" r="40" fill="#fbbf24"/>${[[55,3,'#a8a29e'],[80,5,'#f5d0a9'],[108,5,'#3b82f6'],[134,4,'#ef4444'],[175,12,'#d4a373'],[220,10,'#e9c46a'],[262,7,'#67e8f9'],[300,7,'#6366f1']].map(([x,r,c],i)=>`<circle cx="0" cy="84" r="${x}" fill="none" stroke="#334155"/><circle cx="${x}" cy="84" r="${r}" fill="${c}"/>${i===5?`<ellipse cx="${x}" cy="84" rx="17" ry="4" fill="none" stroke="#fde68a" stroke-width="2"/>`:''}`).join('')}</svg>`,
sesi:[
{j:'Matahari', h:`<p>Matahari adalah <b>bintang</b> — bola gas raksasa (terutama hidrogen dan helium) yang memancarkan cahaya sendiri. Massanya ±99,8% massa seluruh tata surya, sehingga gravitasinya menahan semua planet.</p><p>Energinya berasal dari <b>reaksi fusi nuklir</b> di inti: atom hidrogen bergabung menjadi helium dan melepaskan energi sangat besar. Suhu inti ±15 juta °C, permukaan (fotosfer) ±5.500°C.</p><p>Lapisan Matahari: inti, zona radiasi, zona konveksi, fotosfer, kromosfer, dan korona. Fenomena: bintik matahari, lidah api (prominensa), dan badai matahari yang dapat mengganggu satelit & memicu aurora.</p><div class="warn">⚠️ Jangan pernah menatap Matahari langsung atau lewat teropong tanpa filter khusus — bisa merusak retina secara permanen.</div>`},
{j:'Delapan planet', h:`<p><b>Planet dalam (terestrial)</b> — kecil, berbatu: Merkurius, Venus, Bumi, Mars. <b>Planet luar (raksasa)</b> — besar, berupa gas/es, bercincin: Jupiter, Saturnus, Uranus, Neptunus. Pembatasnya adalah sabuk asteroid.</p><div class="tbl"><table><tr><th>Planet</th><th>Ciri khas</th></tr><tr><td>Merkurius</td><td>terdekat & terkecil; suhu siang-malam ekstrem</td></tr><tr><td>Venus</td><td>terpanas (efek rumah kaca), paling terang di langit, berotasi berlawanan arah</td></tr><tr><td>Bumi</td><td>satu-satunya yang diketahui berpenghuni; punya air cair & atmosfer kaya oksigen</td></tr><tr><td>Mars</td><td>planet merah (debu besi oksida); punya gunung tertinggi di tata surya, Olympus Mons</td></tr><tr><td>Jupiter</td><td>terbesar; Bintik Merah Besar adalah badai raksasa</td></tr><tr><td>Saturnus</td><td>cincin paling indah; massa jenis lebih kecil dari air</td></tr><tr><td>Uranus</td><td>sumbu rotasi miring ±98° (seperti menggelinding)</td></tr><tr><td>Neptunus</td><td>terjauh; angin tercepat di tata surya</td></tr></table></div><div class="note">🧠 Urutan: <b>“Mak Ve Bu Ma Ju Sa U Ne”</b>. Sejak 2006 Pluto digolongkan sebagai <b>planet kerdil</b> karena orbitnya tidak “bersih” dari benda lain.</div>`},
{j:'Satelit, asteroid, komet, meteor', h:`<ul><li><b>Satelit alami</b>: benda yang mengelilingi planet, misalnya Bulan. Jupiter dan Saturnus memiliki sangat banyak satelit.</li><li><b>Asteroid</b>: batuan kecil yang mengorbit Matahari, kebanyakan di sabuk asteroid antara Mars dan Jupiter.</li><li><b>Komet</b>: “bola salju kotor” dari es dan debu dengan orbit sangat lonjong. Saat mendekati Matahari, es menguap membentuk ekor yang selalu <b>menjauhi Matahari</b>. Komet Halley terlihat dari Bumi kira-kira tiap 76 tahun.</li><li><b>Meteoroid</b> → disebut <b>meteor</b> (“bintang jatuh”) saat terbakar di atmosfer → disebut <b>meteorit</b> jika sisanya sampai ke permukaan Bumi.</li></ul>`},
{j:'Rotasi & revolusi Bumi', h:`<p><b>Rotasi</b>: Bumi berputar pada porosnya dari barat ke timur, sekali dalam ±24 jam. Akibatnya:</p><ul><li>terjadi siang dan malam;</li><li>gerak semu harian Matahari (terbit di timur, terbenam di barat);</li><li>perbedaan waktu antartempat — setiap 15° bujur berbeda 1 jam (Indonesia: WIB, WITA, WIT);</li><li>pembelokan arah angin dan arus laut.</li></ul><p><b>Revolusi</b>: Bumi mengelilingi Matahari sekali dalam ±365¼ hari. Akibatnya:</p><ul><li>pergantian musim (karena sumbu Bumi miring 23,5°);</li><li>gerak semu tahunan Matahari (bergeser antara 23,5° LU dan 23,5° LS);</li><li>perbedaan lama siang dan malam;</li><li>rasi bintang yang tampak berganti sepanjang tahun;</li><li>tahun kabisat: sisa ¼ hari dikumpulkan tiap 4 tahun menjadi 29 Februari.</li></ul>`},
{j:'Bulan: fase, gerhana, pasang surut', h:`<p>Bulan berotasi dan berevolusi dalam waktu yang sama (±27,3 hari), sehingga sisi yang menghadap Bumi selalu sama. Dari satu bulan purnama ke purnama berikutnya ±29,5 hari — dasar kalender Hijriah.</p><p><b>Fase bulan</b>: bulan baru → sabit → kuartir pertama (separuh) → cembung → purnama → cembung → kuartir akhir → sabit → bulan baru. Bentuknya berubah karena kita melihat bagian Bulan yang tersinari Matahari dari sudut berbeda.</p><ul><li><b>Gerhana Matahari</b>: Bulan berada di antara Matahari dan Bumi (saat bulan baru). Jenis: total, sebagian, cincin.</li><li><b>Gerhana Bulan</b>: Bumi berada di antara Matahari dan Bulan (saat purnama). Bulan bisa tampak kemerahan.</li></ul><p><b>Pasang surut</b> air laut terutama disebabkan gaya gravitasi Bulan (dibantu Matahari). Pasang paling tinggi terjadi saat bulan baru dan purnama.</p>`},
],
penemuan:`<h4>🌍 Bumi pusat atau Matahari pusat?</h4><div class="tl"><div><b>±150 M — Ptolemaeus</b> mengajarkan <b>geosentris</b>: Bumi diam di pusat alam semesta. Model ini dipercaya lebih dari 1.400 tahun.</div><div><b>1543 — Nicolaus Copernicus</b> menerbitkan model <b>heliosentris</b>: Matahari di pusat, Bumi berputar dan mengelilinginya. Model ini menjelaskan gerak planet dengan lebih sederhana.</div><div><b>1609–1610 — Galileo Galilei</b> mengarahkan teleskop ke langit: melihat empat bulan Jupiter (bukti tidak semua benda mengelilingi Bumi), fase Venus seperti fase Bulan (hanya mungkin jika Venus mengelilingi Matahari), kawah Bulan, dan bintik Matahari.</div><div><b>1609–1619 — Johannes Kepler</b>, dengan data pengamatan teliti Tycho Brahe, menemukan orbit planet berbentuk <b>elips</b> dan merumuskan tiga hukum Kepler.</div><div><b>1687 — Isaac Newton</b> menjelaskan <i>mengapa</i> planet beredar: gaya gravitasi Matahari.</div><div><b>1781 — William Herschel</b> menemukan Uranus dengan teleskop.</div><div><b>1846 — Neptunus</b> ditemukan berkat matematika! Urbain Le Verrier menghitung posisi planet tak dikenal yang mengganggu orbit Uranus; Johann Galle mengarahkan teleskop ke titik itu dan menemukannya pada malam yang sama.</div></div><h4>🧮 Mengapa 15° = 1 jam?</h4><p>Bumi berputar satu putaran penuh (360°) dalam 24 jam. Jadi dalam 1 jam Bumi berputar 360° : 24 = <b>15°</b>. Wilayah yang lebih ke timur melihat Matahari terbit lebih dulu, sehingga waktunya lebih cepat.</p>`,
rumus:[['360° : 24 jam = 15° per jam','selisih bujur → selisih waktu'],['1° bujur = 4 menit','turunan dari 15° = 60 menit'],['Kabisat: tahun habis dibagi 4','29 Februari (kecuali tahun abad yang tidak habis dibagi 400)'],['Bulan sinodis ≈ 29,5 hari','purnama ke purnama']],
contoh:[
{s:'Di Jakarta (WIB) pukul 08.00. Pukul berapa di Makassar (WITA) dan Jayapura (WIT)?', l:['WITA = WIB + 1 jam.','WIT = WIB + 2 jam.'], j:'Makassar pukul 09.00, Jayapura pukul 10.00'},
{s:'Kota A berada di 105° BT dan kota B di 135° BT. Berapa selisih waktunya?', l:['Selisih bujur = 135° − 105° = 30°.','Setiap 15° = 1 jam → 30° : 15° = 2 jam.','Kota B (lebih timur) lebih cepat.'], j:'Selisih 2 jam; kota B lebih dulu'},
{s:'Apakah tahun 2028 tahun kabisat? Berapa hari Februari tahun itu?', l:['2028 : 4 = 507 tanpa sisa.','Tahun yang habis dibagi 4 (dan bukan tahun abad) adalah kabisat.'], j:'2028 tahun kabisat; Februari 29 hari'},
],
kuis:{bahas:'ciri Matahari, karakteristik delapan planet, benda langit lain, akibat rotasi dan revolusi Bumi, fase bulan, dan gerhana', soal:[
{q:'Planet terbesar dalam tata surya adalah…', o:['Saturnus','Jupiter','Neptunus','Bumi'], a:1, p:'Jupiter memiliki diameter ±11 kali diameter Bumi, terbesar di antara semua planet.'},
{q:'Akibat rotasi Bumi adalah…', o:['pergantian musim','terjadinya siang dan malam','tahun kabisat','gerhana bulan'], a:1, p:'Saat berputar pada porosnya, sisi Bumi yang menghadap Matahari mengalami siang dan sisi sebaliknya malam. Musim dan tahun kabisat adalah akibat revolusi.'},
{q:'Gerhana bulan terjadi ketika…', o:['Bulan berada di antara Matahari dan Bumi','Bumi berada di antara Matahari dan Bulan','Matahari berada di antara Bumi dan Bulan','Bulan berada di belakang Matahari'], a:1, p:'Pada gerhana bulan, bayangan Bumi menutupi Bulan. Itu hanya bisa terjadi jika Bumi berada di antara Matahari dan Bulan (saat purnama).'},
{q:'Benda langit yang tidak habis terbakar di atmosfer dan jatuh ke permukaan Bumi disebut…', o:['meteor','meteorit','komet','asteroid'], a:1, p:'Meteoroid yang terbakar di atmosfer disebut meteor; sisa yang sampai ke permukaan Bumi disebut meteorit.'},
{q:'Dua kota berbeda bujur 45°. Selisih waktunya…', o:['3 jam','45 menit','4,5 jam','1 jam'], a:0, p:'Setiap 15° bujur = 1 jam, jadi 45° : 15° = 3 jam.'},
]}});
